// Package logging provides the structured logging used by gomplate.
package logging

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"os"
	"strconv"
	"time"
	"unicode/utf8"
)

// Format identifies one of the supported log output formats.
type Format string

// supported log formats
const (
	FormatJSON    Format = "json"
	FormatConsole Format = "console"
	FormatLogfmt  Format = "logfmt"
	FormatSimple  Format = "simple"
)

// env var used to select the log format
const formatEnvVar = "GOMPLATE_LOG_FORMAT"

// Level abbreviations used by the console formatter.
var levelNames = map[slog.Level]string{
	slog.LevelDebug: "DBG",
	slog.LevelInfo:  "INF",
	slog.LevelWarn:  "WRN",
	slog.LevelError: "ERR",
}

// levelColors maps levels to the ANSI colour used by the console formatter.
var levelColors = map[slog.Level]string{
	slog.LevelDebug: "",
	slog.LevelInfo:  "",
	slog.LevelWarn:  "\x1b[93m",
	slog.LevelError: "\x1b[91m",
}

const (
	colorDim  = "\x1b[2m"
	colorBold = "\x1b[1m"
	colorOff  = "\x1b[0m"
)

// Logger is the interface used throughout gomplate for logging.
type Logger = *slog.Logger

// NewHandler creates a handler that writes log records in the given format.
func NewHandler(format Format, w io.Writer, level slog.Leveler) (slog.Handler, error) {
	switch format {
	case FormatJSON:
		return slog.NewJSONHandler(w, &slog.HandlerOptions{Level: level}), nil
	case FormatLogfmt:
		return slog.NewTextHandler(w, &slog.HandlerOptions{Level: level}), nil
	case FormatSimple:
		return &simpleHandler{w: w, level: level}, nil
	case FormatConsole:
		return &consoleHandler{w: w, level: level}, nil
	}
	return nil, fmt.Errorf("not allowed value for the log format: %s", format)
}

// ParseFormat reads the log format from the environment.
func ParseFormat(isTTY bool) Format {
	f := Format(os.Getenv(formatEnvVar))
	switch f {
	case FormatJSON, FormatConsole, FormatLogfmt, FormatSimple:
		return f
	}
	if isTTY {
		return FormatConsole
	}
	return FormatJSON
}

// NewLogger creates a logger for the given format writing to stderr.
func NewLogger(format Format, level slog.Leveler) (Logger, error) {
	h, err := NewHandler(format, os.Stderr, level)
	if err != nil {
		return nil, err
	}
	return slog.New(h), nil
}

// simpleHandler writes a very simple, unstructured log format.
type simpleHandler struct {
	w     io.Writer
	level slog.Leveler
	attrs []slog.Attr
}

func (h *simpleHandler) Enabled(_ context.Context, l slog.Level) bool { return l >= h.level.Level() }

func (h *simpleHandler) Handle(_ context.Context, r slog.Record) error {
	buf := make([]byte, 0, 256)
	buf = append(buf, "  "...)
	buf = append(buf, r.Message...)
	if r.NumAttrs() > 0 || len(h.attrs) > 0 {
		buf = append(buf, ' ')
	}
	for _, a := range h.attrs {
		buf = h.appendAttr(buf, a)
	}
	r.Attrs(func(a slog.Attr) bool {
		buf = h.appendAttr(buf, a)
		return true
	})
	buf = append(buf, '\n')
	_, err := h.w.Write(buf)
	return err
}

func (h *simpleHandler) appendAttr(buf []byte, a slog.Attr) []byte {
	if a.Equal(slog.Attr{}) {
		return buf
	}
	buf = append(buf, a.Key...)
	buf = append(buf, '=')
	buf = appendValue(buf, a.Value)
	buf = append(buf, ' ')
	return buf
}

func (h *simpleHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	n := *h
	n.attrs = append(append([]slog.Attr{}, h.attrs...), attrs...)
	return &n
}

func (h *simpleHandler) WithGroup(name string) slog.Handler {
	return h
}

func appendValue(buf []byte, v slog.Value) []byte {
	switch v.Kind() {
	case slog.KindString:
		s := v.String()
		if needsQuoting(s) {
			return strconv.AppendQuote(buf, s)
		}
		return append(buf, s...)
	case slog.KindInt64, slog.KindUint64, slog.KindFloat64, slog.KindBool:
		return append(buf, fmt.Sprintf("%v", v.Any())...)
	default:
		s := fmt.Sprintf("%v", v.Any())
		if needsQuoting(s) {
			return strconv.AppendQuote(buf, s)
		}
		return append(buf, s...)
	}
}

func (h *simpleHandler) valueString(v slog.Value) string {
	switch v.Kind() {
	case slog.KindGroup:
		var out string
		for _, a := range v.Group() {
			out += h.valueString(a.Value)
		}
		return out
	default:
		return fmt.Sprintf("%v", v.Any())
	}
}

// consoleHandler writes human-readable, colourised log output.
type consoleHandler struct {
	w     io.Writer
	level slog.Leveler
	attrs []slog.Attr
}

func (h *consoleHandler) Enabled(_ context.Context, l slog.Level) bool { return l >= h.level.Level() }

func (h *consoleHandler) Handle(_ context.Context, r slog.Record) error {
	buf := make([]byte, 0, 256)
	buf = append(buf, colorDim...)
	buf = append(buf, r.Time.Format("15:04:05")...)
	buf = append(buf, colorOff...)
	buf = append(buf, ' ')
	if col, ok := levelColors[r.Level]; ok && col != "" {
		buf = append(buf, col...)
	}
	buf = append(buf, levelName(r.Level)...)
	if col, ok := levelColors[r.Level]; ok && col != "" {
		buf = append(buf, colorOff...)
	}
	buf = append(buf, ' ')
	buf = append(buf, r.Message...)
	if r.NumAttrs() > 0 || len(h.attrs) > 0 {
		buf = append(buf, ' ')
	}
	for _, a := range h.attrs {
		buf = h.appendAttr(buf, a)
	}
	r.Attrs(func(a slog.Attr) bool {
		buf = h.appendAttr(buf, a)
		return true
	})
	buf = append(buf, '\n')
	_, err := h.w.Write(buf)
	return err
}

func (h *consoleHandler) appendAttr(buf []byte, a slog.Attr) []byte {
	if a.Equal(slog.Attr{}) {
		return buf
	}
	buf = append(buf, colorDim...)
	buf = append(buf, a.Key...)
	buf = append(buf, '=')
	buf = append(buf, colorOff...)
	s := valueString(a.Value)
	if needsQuoting(s) {
		buf = strconv.AppendQuote(buf, s)
	} else {
		buf = append(buf, s...)
	}
	buf = append(buf, ' ')
	return buf
}

func (h *consoleHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	n := *h
	n.attrs = append(append([]slog.Attr{}, h.attrs...), attrs...)
	return &n
}

func (h *consoleHandler) WithGroup(name string) slog.Handler { return h }

func levelName(l slog.Level) string {
	if n, ok := levelNames[l]; ok {
		return n
	}
	switch {
	case l < slog.LevelInfo:
		return "DBG"
	case l < slog.LevelWarn:
		return "INF"
	case l < slog.LevelError:
		return "WRN"
	}
	return "ERR"
}

func valueString(v slog.Value) string {
	switch v.Kind() {
	case slog.KindGroup:
		out := ""
		for _, a := range v.Group() {
			out += a.Key + "=" + valueString(a.Value) + " "
		}
		return out
	default:
		return fmt.Sprintf("%v", v.Any())
	}
}

// needsQuoting reports whether a string value needs to be quoted when written
// to a key=value style log line.
func needsQuoting(s string) bool {
	if len(s) == 0 {
		return true
	}
	for i := 0; i < len(s); {
		b := s[i]
		if b < utf8.RuneSelf {
			if b != '\\' && (b == ' ' || b == '=' || !safeSet[b]) {
				return true
			}
			i++
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError || r == ' ' || r == '=' {
			return true
		}
		i += size
	}
	return false
}

var safeSet = func() [utf8.RuneSelf]bool {
	var s [utf8.RuneSelf]bool
	for i := 0x20; i < utf8.RuneSelf; i++ {
		s[i] = true
	}
	s['"'] = false
	s['\\'] = false
	return s
}()

var _ = time.Time{}
EOF
