package config

import "os"

// FlagVals holds the values of the command-line flags relevant to the config.
type FlagVals struct {
	In                        string
	InChanged                 bool
	InputFiles                []string
	InputFilesChanged         bool
	InputDir                  string
	InputDirChanged           bool
	OutputFiles               []string
	OutputFilesChanged        bool
	OutputDir                 string
	OutputDirChanged          bool
	OutputMap                 string
	OutputMapChanged          bool
	Excludes                  []string
	ExcludesChanged           bool
	ExcludeProcessing         []string
	ExcludeProcessingChanged  bool
	Chmod                     string
	ChmodChanged              bool
	LeftDelim                 string
	LeftDelimChanged          bool
	RightDelim                string
	RightDelimChanged         bool
	MissingKey                string
	MissingKeyChanged         bool
	PostExec                  []string
	PostExecChanged           bool
	ExecPipe                  bool
	ExecPipeChanged           bool
	PluginTimeout             string
	PluginTimeoutChanged      bool
	Experimental              bool
	ExperimentalChanged       bool
	Datasources               []string
	DatasourcesChanged        bool
	DataSourceHeaders         []string
	DataSourceHeadersChanged  bool
	Context                   []string
	ContextChanged            bool
	Templates                 []string
	TemplatesChanged          bool
	Plugins                   []string
	PluginsChanged            bool
}

// emptyFileConfig returns a config with no values set at all.
func emptyFileConfig() *Config {
	return &Config{
		Datasources: map[string]raw{},
		Context:     map[string]raw{},
		Templates:   map[string]raw{},
		Plugins:     map[string]pluginConfig{},
	}
}

// applyFlagsFile applies command-line flags to a config that was loaded from a
// configuration file. Mutually-exclusive options set on the command-line take
// precedence over, and reset, conflicting options from the config file.
func applyFlagsFile(cfg *Config, fv *FlagVals) {
	if fv.InputFilesChanged {
		cfg.InputFiles = fv.InputFiles
		cfg.In = ""
		cfg.InputDir = ""
		cfg.OutputDir = ""
	}
	if fv.InputDirChanged {
		cfg.InputDir = fv.InputDir
		cfg.In = ""
		cfg.InputFiles = nil
	}
	if fv.InChanged {
		cfg.In = fv.In
		cfg.InputFiles = nil
		cfg.InputDir = ""
		cfg.OutputDir = ""
	}
	if fv.ExcludesChanged {
		cfg.Excludes = fv.Excludes
	}
	if fv.ExcludeProcessingChanged {
		cfg.ExcludeProcessing = fv.ExcludeProcessing
	}
	if fv.OutputMapChanged {
		cfg.OutputMap = fv.OutputMap
		cfg.OutputDir = ""
		cfg.OutputFiles = nil
	}
	if fv.OutputDirChanged {
		cfg.OutputDir = fv.OutputDir
		cfg.OutputMap = ""
		cfg.OutputFiles = nil
	}
	if fv.OutputFilesChanged {
		cfg.OutputFiles = fv.OutputFiles
		cfg.OutputDir = ""
		cfg.OutputMap = ""
	}
	if fv.ChmodChanged {
		cfg.Chmod = fv.Chmod
	}
	if fv.LeftDelimChanged {
		cfg.LeftDelim = fv.LeftDelim
	}
	if fv.RightDelimChanged {
		cfg.RightDelim = fv.RightDelim
	}
	if fv.MissingKeyChanged {
		cfg.MissingKey = fv.MissingKey
	}
	if fv.PostExecChanged {
		cfg.PostExec = fv.PostExec
	}
	if fv.ExecPipeChanged {
		cfg.ExecPipe = true
		cfg.OutputFiles = []string{"-"}
	}
	if fv.PluginTimeoutChanged {
		cfg.PluginTimeout = fv.PluginTimeout
	}
	if fv.ExperimentalChanged {
		cfg.Experimental = true
	}
	if fv.DatasourcesChanged {
		if cfg.Datasources == nil {
			cfg.Datasources = map[string]raw{}
		}
		addRaw(cfg.Datasources, fv.Datasources, fv.DataSourceHeaders)
	}
	if fv.ContextChanged {
		if cfg.Context == nil {
			cfg.Context = map[string]raw{}
		}
		addRaw(cfg.Context, fv.Context, fv.DataSourceHeaders)
	}
	if fv.TemplatesChanged {
		if cfg.Templates == nil {
			cfg.Templates = map[string]raw{}
		}
		addRaw(cfg.Templates, fv.Templates, fv.DataSourceHeaders)
	}
	if fv.PluginsChanged {
		if cfg.Plugins == nil {
			cfg.Plugins = map[string]pluginConfig{}
		}
		addPlugins(cfg.Plugins, fv.Plugins)
