func parseHeader(h string) (alias, name string, value string, ok bool) {
	alias, rest := splitAliasURL(h)
	idx := -1
	for i := 0; i < len(rest); i++ {
		if rest[i] == ':' {
			idx = i
			break
		}
	}
	if idx < 0 {
		return "", "", "", false
	}
	name = rest[:idx]
	value = rest[idx+1:]
	return alias, name, value, true
}

// fromEnv fills in configuration values from the environment where the option
// was not set by a flag or the config file.
func (c *Config) fromEnv() {
	if c.LeftDelim == "" {
		c.LeftDelim = os.Getenv(envLeftDelim)
	}
	if c.RightDelim == "" {
		c.RightDelim = os.Getenv(envRightDelim)
	}
	if !c.Experimental {
		if v := os.Getenv(envExperimental); v != "" {
			b, err := parseBool(v)
			if err == nil {
				c.Experimental = b
			}
		}
	}
	if c.PluginTimeout == "" {
		c.PluginTimeout = os.Getenv(envPluginTimeout)
	}
}
