	}
	return b, nil
}

// applyDefaults fills in defaults for options not set elsewhere.
func (c *Config) applyDefaults() {
	c.resolveEnv()
	if c.In == "" && c.InputDir == "" && len(c.InputFiles) == 0 {
		c.InputFiles = []string{"-"}
	}
	skipOutput := c.OutputMap != "" ||
		((c.In != "" || len(c.InputFiles) > 0 || c.InputDir != "") && c.OutputDir != "")
	if len(c.OutputFiles) == 0 && !skipOutput {
		c.OutputFiles = []string{"-"}
	}
