		c.MissingKey = "error"
	}
	if c.PluginTimeout == "" {
		c.PluginTimeout = pluginTimeoutDefault
	}
}

// allowedMissingKeyValues are the values accepted for the missing-key option.
var allowedMissingKeyValues = []string{"", "error", "zero", "default", "invalid"}

// Validate checks that the configuration is internally consistent.
func (c *Config) Validate() error {
	if c.In != "" && len(c.InputFiles) > 0 {
		return fmt.Errorf("only one of these options is supported at a time: 'in', 'inputFiles'")
	}
	if c.In != "" && c.InputDir != "" {
		return fmt.Errorf("only one of these options is supported at a time: 'in', 'inputDir'")
	}
	if len(c.InputFiles) > 0 && c.InputDir != "" {
		return fmt.Errorf("only one of these options is supported at a time: 'inputFiles', 'inputDir'")
	}
	if len(c.OutputFiles) > 0 && c.OutputDir != "" {
		return fmt.Errorf("only one of these options is supported at a time: 'outputFiles', 'outputDir'")
	}
	if len(c.OutputFiles) > 0 && c.OutputMap != "" {
		return fmt.Errorf("only one of these options is supported at a time: 'outputFiles', 'outputMap'")
	}
	if c.OutputDir != "" && c.OutputMap != "" {
		return fmt.Errorf("only one of these options is supported at a time: 'outputDir', 'outputMap'")
	}
	inputs := len(c.InputFiles)
	if c.In != "" {
		inputs = 1
	}
	if len(c.OutputFiles) > 0 && len(c.OutputFiles) != inputs {
		return fmt.Errorf("must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options",
			len(c.OutputFiles), inputs)
	}
	if c.OutputDir != "" && c.InputDir == "" {
		return fmt.Errorf("these options must be set together: 'outputDir', 'inputDir'")
	}
	if c.OutputMap != "" && c.InputDir == "" {
		return fmt.Errorf("these options must be set together: 'outputMap', 'inputDir'")
	}
	if c.ExecPipe && len(c.PostExec) == 0 {
		return fmt.Errorf("execPipe may only be used with a postExec command")
	}
	found := false
	for _, v := range allowedMissingKeyValues {
		if v == c.MissingKey {
			found = true
			break
		}
	}
	if !found {
		return fmt.Errorf("not allowed value for the 'missing-key' flag: %s. Allowed values: %s",
			c.MissingKey, strings.Join(allowedMissingKeyValues, ","))
	}
	return nil
