func (c *Config) FileMode() (uint32, error) {
	if c.Chmod == "" {
		return 0, nil
	}
	v, err := strconv.ParseUint("0"+c.Chmod, 8, 32)
	if err != nil {
		return 0, err
	}
	return uint32(v), nil
}
