// Package config handles gomplate's configuration, including loading
// configuration from a file and merging it with command-line flags.
package config

import (
	"fmt"
	"os"
	"strings"

	"github.com/spf13/pflag"
	yaml "gopkg.in/yaml.v3"
)

// Environment variables understood by gomplate.
const (
	EnvConfig         = "GOMPLATE_CONFIG"
	EnvLeftDelim      = "GOMPLATE_LEFT_DELIM"
	EnvRightDelim     = "GOMPLATE_RIGHT_DELIM"
	EnvExperimental   = "GOMPLATE_EXPERIMENTAL"
	EnvPluginTimeout  = "GOMPLATE_PLUGIN_TIMEOUT"
	EnvTypeParam      = "GOMPLATE_TYPE_PARAM"
	EnvLogFormat      = "GOMPLATE_LOG_FORMAT"
	DefaultConfigFile = ".gomplate.yaml"
)

// raw is the source of a datasource, template, or context value.
type raw struct {
	URL    string
	Header map[string][]string
}

// MarshalYAML implements yaml.Marshaler.
func (r raw) MarshalYAML() (interface{}, error) {
	return &struct {
		Header map[string][]string `yaml:"header"`
		URL    string              `yaml:"url,omitempty"`
	}{Header: r.Header, URL: r.URL}, nil
}

// UnmarshalYAML implements yaml.Unmarshaler.
func (r *raw) UnmarshalYAML(value *yaml.Node) error {
	if value.Kind == yaml.ScalarNode {
		r.URL = value.Value
		return nil
	}
	type alias struct {
		URL    string              `yaml:"url"`
		Header map[string][]string `yaml:"header"`
	}
	var a alias
	if err := value.Decode(&a); err != nil {
		return err
	}
	r.URL = a.URL
	r.Header = a.Header
	return nil
}

// pluginConfig holds the configuration for an external plugin command.
type pluginConfig struct {
	Cmd     string
	Args    []string
	Timeout string
	Pipe    bool
}

// MarshalYAML implements yaml.Marshaler.
func (p pluginConfig) MarshalYAML() (interface{}, error) {
	return &struct {
		Cmd     string   `yaml:"cmd,omitempty"`
		Args    []string `yaml:"args,omitempty"`
		Timeout string   `yaml:"timeout,omitempty"`
		Pipe    bool     `yaml:"pipe,omitempty"`
	}{Cmd: p.Cmd, Args: p.Args, Timeout: p.Timeout, Pipe: p.Pipe}, nil
}

// UnmarshalYAML implements yaml.Unmarshaler.
func (p *pluginConfig) UnmarshalYAML(value *yaml.Node) error {
	if value.Kind == yaml.ScalarNode {
		p.Cmd = value.Value
		return nil
	}
	type alias struct {
		Cmd     string   `yaml:"cmd"`
		Args    []string `yaml:"args"`
		Timeout string   `yaml:"timeout"`
		Pipe    bool     `yaml:"pipe"`
	}
	var a alias
	if err := value.Decode(&a); err != nil {
		return err
	}
	*p = pluginConfig(a)
	return nil
}

// Config holds the configuration used by gomplate when rendering templates.
type Config struct {
	Datasources       map[string]raw          `yaml:"datasources,omitempty"`
	Context           map[string]raw          `yaml:"context,omitempty"`
	Templates         map[string]raw          `yaml:"templates,omitempty"`
	Plugins           map[string]pluginConfig `yaml:"plugins,omitempty"`
	In                string                  `yaml:"in,omitempty"`
	InputFiles        []string                `yaml:"inputFiles,omitempty,flow"`
	InputDir          string                  `yaml:"inputDir,omitempty"`
	Excludes          []string                `yaml:"excludes,omitempty"`
	ExcludeProcessing []string                `yaml:"excludeProcessing,omitempty"`
	OutputDir         string                  `yaml:"outputDir,omitempty"`
	OutputMap         string                  `yaml:"outputMap,omitempty"`
	OutputFiles       []string                `yaml:"outputFiles,omitempty,flow"`
	Chmod             string                  `yaml:"chmod,omitempty"`
	LeftDelim         string                  `yaml:"leftDelim,omitempty"`
	RightDelim        string                  `yaml:"rightDelim,omitempty"`
	MissingKey        string                  `yaml:"missingKey,omitempty"`
	PostExec          []string                `yaml:"postExec,omitempty,flow"`
	ExecPipe          bool                    `yaml:"execPipe,omitempty"`
	PluginTimeout     string                  `yaml:"pluginTimeout,omitempty"`
	Experimental      bool                    `yaml:"experimental,omitempty"`

	configFile string
}

// ConfigFile returns the path of the configuration file used, if any.
func (c *Config) ConfigFile() string {
	if c == nil {
		return ""
	}
	return c.configFile
}

// NewConfigFromFlags creates a configuration by combining the configuration
// file (if any) with the provided command-line flags.
func NewConfigFromFlags(fv *FlagVals, configFilePath string) (*Config, error) {
	cfg := &Config{}
	if configFilePath != "" {
		data, err := os.ReadFile(strings.TrimPrefix(configFilePath, "/"))
		if err != nil {
			return nil, fmt.Errorf("config file requested, but couldn't be opened: %w", err)
		}
		if len(data) > 0 {
			if err := yaml.Unmarshal(data, cfg); err != nil {
				return nil, fmt.Errorf("parsing config file %q: YAML decoding failed, syntax may be invalid: %w", configFilePath, err)
			}
			cfg.initHeaders()
		}
		cfg.configFile = configFilePath
		applyFlagsFile(cfg, fv)
		return cfg, nil
	}
	applyFlagsDirect(cfg, fv)
	return cfg, nil
}

// initHeaders makes sure datasource, context, and template entries all have a
// (possibly empty) header map.
func (c *Config) initHeaders() {
	for k, v := range c.Datasources {
		if v.Header == nil {
			v.Header = map[string][]string{}
			c.Datasources[k] = v
		}
	}
	for k, v := range c.Context {
		if v.Header == nil {
			v.Header = map[string][]string{}
			c.Context[k] = v
		}
	}
	for k, v := range c.Templates {
		if v.Header == nil {
			v.Header = map[string][]string{}
			c.Templates[k] = v
		}
	}
}

// MarshalYAML implements yaml.Marshaler, used for dumping the configuration.
func (c Config) MarshalYAML() (interface{}, error) {
	type alias Config
	a := alias(c)
	return &a, nil
}

var _ = pflag.ErrHelp
