func (d *dirFlag) Type() string { return "directory" }

// delimFlag is a template delimiter option.
type delimFlag struct {
	value string
}

func (d *delimFlag) String() string { return d.value }
func (d *delimFlag) Set(v string) error {
	d.value = v
	return nil
}
func (d *delimFlag) Type() string { return "delimiter" }

// stringsFlag is a repeatable string option.
type stringsFlag struct {
	values []string
}

func (s *stringsFlag) String() string { return strings.Join(s.values, ",") }
func (s *stringsFlag) Set(v string) error {
	s.values = append(s.values, v)
	return nil
}
func (s *stringsFlag) Type() string { return "strings" }

// opts holds the parsed command-line options.
type opts struct {
	datasource        datasourceFlag
	header            headerFlag
	context           datasourceFlag
	plugin            stringsFlag
	file              fileFlag
	in                string
	inputDir          dirFlag
	exclude           stringsFlag
	excludeProcessing stringsFlag
	include           stringsFlag
	out               fileFlag
	template          stringsFlag
	outputDir         dirFlag
	outputMap         string
	chmod             string
	execPipe          bool
	leftDelim         delimFlag
	rightDelim        delimFlag
	missingKey        string
	experimental      bool
	verbose           bool
	config            string

	flags *pflag.FlagSet
}

// NewRootCommand builds the gomplate command.
func NewRootCommand() (*cobra.Command, *opts) {
	o := &opts{}
	cmd := &cobra.Command{
		Use:     "gomplate",
		Short:   "Process text files with Go templates",
		Version: version,
		RunE:    o.run,
	}
	cmd.Flags().SortFlags = false
	f := cmd.Flags()
	o.flags = f

	f.VarP(&o.datasource, "datasource", "d", "datasource in alias=URL form. Specify multiple times to add multiple sources.")
	f.VarP(&o.header, "datasource-header", "H", "HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.")
	f.VarP(&o.context, "context", "c", "pre-load a datasource into the context, in alias=URL form. Use the special alias `.` to set the root context.")
	f.Var(&o.plugin, "plugin", "plug in an external command as a function in name=path form. Can be specified multiple times")
	f.VarPF(&o.file, "file", "f", "Template file to process. Omit to use standard input, or use --in or --input-dir")
	f.StringVarP(&o.in, "in", "i", "", "Template string to process (alternative to --file and --input-dir)")
	f.Var(&o.inputDir, "input-dir", "directory which is examined recursively for templates (alternative to --file and --in)")
	f.Var(&o.exclude, "exclude", "glob of files to not parse")
	f.Var(&o.excludeProcessing, "exclude-processing", "glob of files to be copied without parsing")
	f.Var(&o.include, "include", "glob of files to parse")
	f.VarP(&o.out, "out", "o", "output file name. Omit to use standard output.")
	f.VarP(&o.template, "template", "t", "Additional template file(s)")
	f.Var(&o.outputDir, "output-dir", "directory to store the processed templates. Only used for --input-dir")
	f.StringVar(&o.outputMap, "output-map", "", "Template string to map the input file to an output path")
	f.StringVar(&o.chmod, "chmod", "", "set the mode for output file(s). Omit to inherit from input file(s)")
	f.BoolVar(&o.execPipe, "exec-pipe", false, "pipe the output to the post-run exec command")
	f.Var(&o.leftDelim, "left-delim", "override the default left-delimiter ["+config.EnvLeftDelim+"]")
	f.Var(&o.rightDelim, "right-delim", "override the default right-delimiter ["+config.EnvRightDelim+"]")
	f.StringVar(&o.missingKey, "missing-key", "error", "Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value>")
	f.BoolVar(&o.experimental, "experimental", false, "enable experimental features ["+config.EnvExperimental+"]")
	f.BoolVarP(&o.verbose, "verbose", "V", false, "output extra information about what gomplate is doing")
	f.StringVar(&o.config, "config", config.DefaultConfigFile, "config file (overridden by commandline flags)")

	return cmd, o
}

func (o *opts) changed(name string) bool {
	fl := o.flags.Lookup(name)
	return fl != nil && fl.Changed
}

// flagVals converts the parsed flags into values consumed by the config package.
func (o *opts) flagVals() *config.FlagVals {
	fv := &config.FlagVals{}
	fv.In = o.in
	fv.InChanged = o.changed("in")
	fv.InputFiles = o.file.values
	fv.InputFilesChanged = o.changed("file")
	fv.InputDir = o.inputDir.value
	fv.InputDirChanged = o.changed("input-dir")
	fv.OutputFiles = o.out.values
	fv.OutputFilesChanged = o.changed("out")
	fv.OutputDir = o.outputDir.value
	fv.OutputDirChanged = o.changed("output-dir")
	fv.OutputMap = o.outputMap
	fv.OutputMapChanged = o.changed("output-map")
	fv.Excludes = o.exclude.values
	fv.ExcludesChanged = o.changed("exclude")
	fv.ExcludeProcessing = o.excludeProcessing.values
	fv.ExcludeProcessingChanged = o.changed("exclude-processing")
	fv.Chmod = o.chmod
	fv.ChmodChanged = o.changed("chmod")
	fv.LeftDelim = o.leftDelim.value
	fv.LeftDelimChanged = o.changed("left-delim")
	fv.RightDelim = o.rightDelim.value
	fv.RightDelimChanged = o.changed("right-delim")
	fv.MissingKey = o.missingKey
	fv.MissingKeyChanged = o.changed("missing-key")
	fv.PostExec = o.postExecArgs()
	fv.PostExecChanged = len(fv.PostExec) > 0
	fv.ExecPipe = o.execPipe
	fv.ExecPipeChanged = o.changed("exec-pipe")
	fv.Experimental = o.experimental
	fv.ExperimentalChanged = o.experimental
	fv.Datasources = o.datasource.values
	fv.DatasourcesChanged = o.changed("datasource")
	fv.DataSourceHeaders = o.header.values
	fv.DataSourceHeadersChanged = o.changed("datasource-header")
	fv.Context = o.context.values
	fv.ContextChanged = o.changed("context")
	fv.Templates = o.template.values
	fv.TemplatesChanged = o.changed("template")
	fv.Plugins = o.plugin.values
	fv.PluginsChanged = o.changed("plugin")
	return fv
}

// postExecArgs returns any arguments following the "--" separator.
func (o *opts) postExecArgs() []string {
	if len(o.flags.Args()) == 0 {
		return nil
	}
	return o.flags.Args()
}

// run is the main entry point for the command.
func (o *opts) run(cmd *cobra.Command, args []string) error {
	configFilePath := o.config
	if configFilePath == "" {
		configFilePath = os.Getenv(config.EnvConfig)
	}
	fv := o.flagVals()
	cfg, err := config.NewConfigFromFlags(fv, configFilePath)
	if err != nil {
		return err
	}
	fmt.Println("config:", cfg)
	_ = strconv.Itoa
	return nil
}
EOF
