	var m map[string]interface{}
	err := yaml.Unmarshal([]byte(in), &m)
	if err != nil {
		// maybe it's an array
		var a []interface{}
		if err2 := yaml.Unmarshal([]byte(in), &a); err2 != nil {
			return nil, err2
		}
		return a, nil
	}
	return m, nil
}
```
✓ This matches: for "hello" → both fail → return err2 (the array error) ✓.

And data.JSON:
```go
