// Package data provides gomplate's datasources: reading data from files, HTTP
// endpoints, environment variables, and other sources.
package data

import (
	"bytes"
	"context"
	"encoding/base64"
	"encoding/csv"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
