	if err := d.read(); err != nil {
		return nil, err
	}
	if d.value != nil {
		return d.value, nil
	}
	if d.dir {
		names := strings.Split(strings.TrimPrefix(string(d.raw), "\x00dir:"), "\x00")
		d.value = names
		return d.value, nil
	}
	v, err := Parse(d.mime, d.content)
	if err != nil {
		d.err = err
		return nil, err
	}
	d.value = v
	return v, nil
}

