}

// NewContext creates an empty datasource context.
func NewContext() *Context {
	return &Context{
		Datasources: map[string]*Datasource{},
		Context:     map[string]*Datasource{},
		Templates:   map[string]*Datasource{},
		client:      &http.Client{},
	}
