// Stdin returns the contents of standard input, reading it once.
func (c *Context) Stdin() []byte {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.stdin == nil {
		b, err := io.ReadAll(os.Stdin)
		if err != nil {
			c.stdin = []byte{}
		} else {
			c.stdin = b
		}
	}
	return c.stdin
}

// AddDatasource registers a new datasource, creating it if needed.
func (c *Context) AddDatasource(alias, url string, headers map[string][]string) (*Datasource, error) {
	d, err := newDatasource(alias, url, headers, c)
	if err != nil {
		return nil, err
	}
	c.Datasources[alias] = d
	return d, nil
}

// AddContextDatasource registers a datasource to be loaded into the context.
func (c *Context) AddContextDatasource(alias, url string, headers map[string][]string) (*Datasource, error) {
