	if err != nil {
		return nil, err
	}
	c.Templates[alias] = d
	return d, nil
}

// newDatasource parses a datasource URL.
func newDatasource(alias, dsurl string, headers map[string][]string, ctx *Context) (*Datasource, error) {
	d := &Datasource{
		Alias:   alias,
		URL:     dsurl,
		Headers: headers,
		ctx:     ctx,
	}
	if headers == nil {
		d.Headers = map[string][]string{}
	}
	u, err := url.Parse(dsurl)
	if err != nil {
		return nil, err
	}
	d.u = u
	if err := d.resolve(); err != nil {
		return nil, err
	}
	return d, nil
}

// resolve determines the filesystem and name for the datasource.
func (d *Datasource) resolve() error {
	scheme := d.u.Scheme
	if scheme == "" {
		// a relative path - use the current working directory
		p, err := absPath(d.u.String())
		if err != nil {
			return err
		}
		d.u = &url.URL{Scheme: "", Path: "/"}
		d.fsURL = &url.URL{Scheme: "file", Host: "", Path: "/"}
		d.fsys = rootFS
		d.name = strings.TrimPrefix(p, "/")
		d.dir = strings.HasSuffix(d.URL, "/") || d.URL == "." || d.URL == ".."
	} else {
		fsURL := *d.u
		if d.u.Opaque {
			fsURL.Opaque = false
			fsURL.Host = ""
			fsURL.Path = "/"
		}
		d.fsURL = &fsURL
		if strings.HasSuffix(fsURL.Path, "/") {
			d.dir = true
		}
		switch scheme {
		case "file":
			p := path.Join("/", firstNonEmpty(d.u.Path, d.u.Opaque))
			d.fsys = rootFS
			d.name = strings.TrimPrefix(p, "/")
		case "env":
			name := strings.TrimPrefix(firstNonEmpty(d.u.Path, d.u.Opaque), "/")
			d.name = name
		case "stdin":
			d.name = ""
		case "http", "https":
			p := path.Join("/", firstNonEmpty(d.u.Path, d.u.Opaque))
			d.fsys = rootFS
			d.name = strings.TrimPrefix(p, "/")
		case "merge":
			d.name = firstNonEmpty(d.u.Opaque, d.u.Path)
			if d.name == "" {
				d.name = "/"
			}
		case "text", "base64", "blob", "ejson":
			return unregistered(scheme, d.fsURL)
		case "vault", "vault+http", "vault+https", "consul", "consul+http", "consul+https",
			"s3", "gs", "git", "git+file", "git+http", "git+https", "git+ssh",
			"aws+smp", "aws+sm", "gcp+meta":
			d.fsys = &remoteFS{scheme: scheme, url: d.u}
			d.name = firstNonEmpty(strings.TrimPrefix(d.u.Path, "/"), d.u.Opaque)
			if d.name == "" {
				d.name = "."
			}
		default:
			return unregistered(scheme, d.fsURL)
		}
	}
	return nil
}

func unregistered(scheme string, fsURL *url.URL) error {
	p := fsURL.String()
	if !strings.HasSuffix(p, "/") {
		p += "/"
	}
	return fmt.Errorf("fsys for path %s: filesystem provider for %q unavailable: no filesystem registered for scheme %q",
		p, p, scheme)
}

func firstNonEmpty(a, b string) string {
	if a != "" {
		return a
	}
	return b
}

func absPath(p string) (string, error) {
	if strings.HasPrefix(p, "/") {
		return path.Clean(p), nil
	}
	cwd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	return path.Clean(path.Join(cwd, p)), nil
}

// read reads the datasource content, caching the result.
func (d *Datasource) read() error {
	if d.loaded {
		return d.err
	}
	d.loaded = true
	switch {
	case d.u.Scheme == "file" || d.u.Scheme == "":
		b, err := d.readFile()
		if err != nil {
			d.err = err
			return err
		}
		d.raw = b
	case d.u.Scheme == "env":
		v, ok := os.LookupEnv(d.name)
		if !ok {
			d.err = fmt.Errorf("couldn't read datasource '%s' (%s): environment variable '%s' not found", d.Alias, d.URL, d.name)
			return d.err
		}
		d.raw = []byte(v)
	case d.u.Scheme == "stdin":
		d.raw = d.ctx.Stdin()
	case d.u.Scheme == "http" || d.u.Scheme == "https":
		b, err := d.readHTTP()
		if err != nil {
			d.err = err
			return err
		}
		d.raw = b
	case d.u.Scheme == "merge":
		v, err := d.readMerge()
		if err != nil {
			d.err = err
			return err
		}
		d.value = v
		d.content = ""
		return nil
	case d.u.Scheme == "text":
		d.raw = []byte(d.u.Opaque)
	case d.u.Scheme == "base64":
		b, err := base64.StdEncoding.DecodeString(d.u.Opaque)
		if err != nil {
			d.err = err
			return err
		}
		d.raw = b
	default:
		err := fmt.Errorf("couldn't read datasource '%s' (%s): unsupported scheme %q", d.Alias, d.URL, d.u.Scheme)
		d.err = err
		return err
	}
	d.content = string(d.raw)
	return nil
}

func (d *Datasource) readFile() ([]byte, error) {
	name := d.name
	if d.u.Scheme == "" {
		// relative path, already resolved
	} else if !strings.HasPrefix(name, "/") {
		name = "/" + name
	}
	f, err := d.fsys.Open(strings.TrimPrefix(name, "/"))
	if err != nil {
		return nil, d.wrap("open", err)
	}
	defer f.Close()
	st, err := f.Stat()
	if err != nil {
		return nil, d.wrap("open", err)
	}
	if st.IsDir() {
		d.dir = true
		entries, err := f.ReadDir(-1)
		if err != nil {
			return nil, d.wrap("open", err)
		}
		names := make([]string, 0, len(entries))
		for _, e := range entries {
			names = append(names, e.Name())
		}
		sort.Strings(names)
		return []byte("\x00dir:" + strings.Join(names, "\x00")), nil
	}
	return io.ReadAll(f)
}

func (d *Datasource) wrap(op string, err error) error {
	return fmt.Errorf("%s (url: %q, name: %q): %w", op, d.fsURL.String(), d.fsPath(), err)
}

// fsPath is the path as used by the underlying filesystem.
func (d *Datasource) fsPath() string {
	switch {
	case d.u.Scheme == "" :
		return d.name
	default:
		return strings.TrimPrefix(d.name, "/")
	}
}

func (d *Datasource) readHTTP() ([]byte, error) {
	ctx := context.Background()
	u := *d.u
	u.Path = d.u.Path
	full := u.String()
	req, err := http.NewRequestWithContext(ctx, http.MethodHead, full, nil)
	if err != nil {
		return nil, d.wrap("stat", err)
	}
	for k, vs := range d.Headers {
		for _, v := range vs {
			req.Header.Add(k, v)
		}
	}
	resp, err := d.ctx.client.Do(req)
	if err != nil {
		return nil, d.wrap("stat", err)
	}
	resp.Body.Close()
	if !d.dir && resp.StatusCode >= 400 {
		return nil, d.wrap("stat", fmt.Errorf("Head %q: unexpected status code %d", full, resp.StatusCode))
	}
	d.mime = resp.Header.Get("Content-Type")

	req2, err := http.NewRequestWithContext(ctx, http.MethodGet, full, nil)
	if err != nil {
		return nil, d.wrap("open", err)
	}
	for k, vs := range d.Headers {
		for _, v := range vs {
			req2.Header.Add(k, v)
		}
	}
	resp2, err := d.ctx.client.Do(req2)
	if err != nil {
		return nil, d.wrap("open", err)
	}
	defer resp2.Body.Close()
	if resp2.StatusCode >= 400 {
		return nil, d.wrap("open", fmt.Errorf("Get %q: unexpected status code %d", full, resp2.StatusCode))
	}
	b, err := io.ReadAll(resp2.Body)
	if err != nil {
		return nil, d.wrap("open", err)
	}
	return b, nil
}

func (d *Datasource) readMerge() (interface{}, error) {
	parts := strings.Split(d.name, "|")
	if len(parts) < 2 {
		return nil, fmt.Errorf("need at least 2 datasources to merge")
	}
	var dst map[string]interface{}
	for i := len(parts) - 1; i >= 0; i-- {
		p := parts[i]
		var v interface{}
		var err error
		if d2, ok := d.ctx.Datasources[p]; ok && p != d.Alias {
			v, err = d2.Value()
		} else {
			d3, err2 := newDatasource(d.Alias, p, nil, d.ctx)
			if err2 != nil {
				return nil, fmt.Errorf("opening merge part %q: %w", p, err2)
			}
			v, err = d3.Value()
		}
		if err != nil {
			return nil, err
		}
		m, ok := v.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("expected a map, got %T", v)
		}
		if dst == nil {
			dst = map[string]interface{}{}
		}
		merge(dst, m)
	}
	return dst, nil
}

func merge(dst, src map[string]interface{}) {
	for k, v := range src {
		if s, ok := v.(map[string]interface{}); ok {
			if d, ok := dst[k].(map[string]interface{}); ok {
				merge(d, s)
				continue
			}
		}
		dst[k] = v
	}
}

