func (d *Datasource) readMerge() (interface{}, error) {
	parts := strings.Split(d.name, "|")
	if len(parts) < 2 {
		return nil, fmt.Errorf("need at least 2 datasources to merge")
	}
	var dst map[string]interface{}
	for i := len(parts) - 1; i >= 0; i-- {
		p := parts[i]
		var v interface{}
		var err error
		if d2, ok := d.ctx.Datasources[p]; ok && p != d.Alias {
			v, err = d2.Value()
		} else {
			d3, err2 := newDatasource(d.Alias, p, nil, d.ctx)
			if err2 != nil {
				return nil, fmt.Errorf("opening merge part %q: %w", p, err2)
			}
			v, err = d3.Value()
		}
		if err != nil {
			return nil, err
		}
		m, ok := v.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("expected a map, got %T", v)
		}
		if dst == nil {
			dst = map[string]interface{}{}
		}
		merge(dst, m)
	}
	return dst, nil
}

func merge(dst, src map[string]interface{}) {
	for k, v := range src {
		if s, ok := v.(map[string]interface{}); ok {
			if d, ok := dst[k].(map[string]interface{}); ok {
				merge(d, s)
				continue
			}
		}
		dst[k] = v
	}
}

// Value returns the parsed value of the datasource.
func (d *Datasource) Value() (interface{}, error) {
	if d.value != nil || (d.loaded && d.err == nil && d.u.Scheme == "merge") {
		return d.value, d.err
	}
	if err := d.read(); err != nil {
		return nil, err
	}
	if d.value != nil {
		return d.value, nil
	}
	if d.dir {
		names := strings.Split(strings.TrimPrefix(string(d.raw), "\x00dir:"), "\x00")
		d.value = names
		return d.value, nil
	}
	v, err := Parse(d.mime, d.content)
	if err != nil {
		d.err = err
		return nil, err
	}
	d.value = v
	return v, nil
}

// Bytes returns the raw content of the datasource.
func (d *Datasource) Bytes() ([]byte, error) {
	if err := d.read(); err != nil {
		return nil, err
	}
	return d.raw, nil
}

// String returns the raw content of the datasource as a string.
func (d *Datasource) String() (string, error) {
	if err := d.read(); err != nil {
		return "", err
	}
	return d.content, nil
}

// Exists reports whether the datasource can be read.
func (d *Datasource) Exists() bool {
	if _, err := d.Value(); err != nil {
		return false
	}
	return true
}

// Parse parses a string of the given MIME type into a Go value.
func Parse(mime, in string) (interface{}, error) {
	m := mime
	if i := strings.Index(m, ";"); i >= 0 {
		m = strings.TrimSpace(m[:i])
	}
	switch m {
	case MimeJSON, MimeJSONArr:
		return parseJSON(in)
	case MimeYAML:
		return parseYAML(in)
	case MimeTOML:
		return parseTOML(in)
	case MimeCSV:
		return parseCSV(in)
	case MimeEnv:
		return parseEnv(in)
	case MimeText, "":
		return in, nil
	}
	return nil, fmt.Errorf("data of type %q not yet supported", m)
}

func parseJSON(in string) (interface{}, error) {
	var m map[string]interface{}
	err := yaml.Unmarshal([]byte(in), &m)
	if err == nil {
		return m, nil
	}
	return parseJSONArray(in)
}

func parseJSONArray(in string) (interface{}, error) {
	var a []interface{}
	if err := yaml.Unmarshal([]byte(in), &a); err != nil {
		return nil, fmt.Errorf("unable to unmarshal array %s: %w", in, err)
	}
	return a, nil
}

func parseYAML(in string) (interface{}, error) {
	var m map[string]interface{}
	if err := yaml.Unmarshal([]byte(in), &m); err == nil {
		return m, nil
	}
	var a []interface{}
	err := yaml.Unmarshal([]byte(in), &a)
	if err != nil {
		return nil, err
	}
	return a, nil
}

func parseTOML(in string) (interface{}, error) {
	var m map[string]interface{}
	if err := toml.Unmarshal([]byte(in), &m); err != nil {
		return nil, fmt.Errorf("unable to unmarshal object %s: %w", in, err)
	}
	return m, nil
}

func parseCSV(in string) (interface{}, error) {
	r := csv.NewReader(strings.NewReader(in))
	rows, err := r.ReadAll()
	if err != nil {
		return nil, fmt.Errorf("unable to unmarshal csv %s: %w", in, err)
	}
	return rows, nil
}

func parseEnv(in string) (interface{}, error) {
	return ParseEnvFile(in)
}

// ParseEnvFile parses a file of KEY=VALUE pairs.
func ParseEnvFile(in string) (map[string]interface{}, error) {
	out := map[string]interface{}{}
	lines := strings.Split(in, "\n")
	for i, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		line = strings.TrimPrefix(line, "export ")
		idx := strings.Index(line, "=")
		if idx < 0 {
			return nil, fmt.Errorf("can't separate key from value for key %q", line)
		}
		key := strings.TrimSpace(line[:idx])
		val := strings.TrimSpace(line[idx+1:])
		if err := checkKey(key); err != nil {
			return nil, err
		}
		out[key] = expandEnvValue(val, out)
	}
	_ = i
	return out, nil
}

func checkKey(key string) error {
	if key == "" {
		return errors.New("line can't be empty")
	}
	for _, c := range key {
		if !(c == '_' || c == '.' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) {
			return fmt.Errorf("unexpected character %q in variable name near %q", string(c), key)
		}
	}
	return nil
}

func expandEnvValue(val string, ctx map[string]interface{}) interface{} {
	if strings.HasPrefix(val, `"`) && strings.HasSuffix(val, `"`) && len(val) > 1 {
		s := val[1 : len(val)-1]
		return unescapeDouble(s)
	}
	if strings.HasPrefix(val, `'`) && strings.HasSuffix(val, `'`) && len(val) > 1 {
		return val[1 : len(val)-1]
	}
	return os.Expand(val, func(k string) string {
		if v, ok := ctx[k]; ok {
			return fmt.Sprintf("%v", v)
		}
		return os.Getenv(k)
	})
}

func unescapeDouble(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				b.WriteByte('\n')
			case 'r':
				b.WriteByte('\r')
			case 't':
				b.WriteByte('\t')
			case '\\':
				b.WriteByte('\\')
			case '"':
				b.WriteByte('"')
			case '$':
				b.WriteByte('$')
			default:
				b.WriteByte('\\')
				b.WriteByte(s[i])
			}
			continue
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

