{"command": "cat > /workspace/internal/funcs/util.go <<'EOF'
package funcs

import (
	"encoding/json"
	"fmt"
	"reflect"
	"strconv"
	"strings"
)

func sprint(args ...interface{}) string {
	var b strings.Builder
	for _, a := range args {
		fmt.Fprint(&b, a)
	}
	return b.String()
}

func sprintln(args ...interface{}) string {
	return sprint(args...) + "\n"
}

func sprintf(format string, args ...interface{}) string {
	return fmt.Sprintf(format, args...)
}

// toStringValue converts a value to a string the way gomplate does.
func toStringValue(in interface{}) string {
	if in == nil {
		return "nil"
	}
	return fmt.Sprintf("%v", in)
}

// toInt64 converts a value to an int64, being permissive about the input format.
func toInt64(in interface{}) (int64, error) {
	switch v := in.(type) {
	case int:
		return int64(v), nil
	case int8:
		return int64(v), nil
	case int16:
		return int64(v), nil
	case int32:
		return int64(v), nil
	case int64:
		return v, nil
	case uint:
		return int64(v), nil
	case uint8:
		return int64(v), nil
	case uint16:
		return int64(v), nil
	case uint32:
		return int64(v), nil
	case uint64:
		return int64(v), nil
	case float32:
		return int64(v), nil
	case float64:
		return int64(v), nil
	case bool:
		if v {
			return 1, nil
		}
		return 0, nil
	case []byte:
		return toInt64(string(v))
	case nil:
		return 0, fmt.Errorf("couldn't convert nil to int64")
	}
	s := strings.ReplaceAll(toStringValue(in), ",", "")
	i, err := strconv.ParseInt(s, 0, 64)
	if err == nil {
		return i, nil
	}
	f, ferr := strconv.ParseFloat(s, 64)
	if ferr != nil {
		return 0, fmt.Errorf("could not convert %q to int64: %w", s, ferr)
	}
	return int64(f), nil
}

// toFloat64 converts a value to a float64.
func toFloat64(in interface{}) (float64, error) {
	switch v := in.(type) {
	case int:
		return float64(v), nil
	case int8:
		return float64(v), nil
	case int16:
		return float64(v), nil
	case int32:
		return float64(v), nil
	case int64:
		return float64(v), nil
	case uint:
		return float64(v), nil
	case uint8:
		return float64(v), nil
	case uint16:
		return float64(v), nil
	case uint32:
		return float64(v), nil
	case uint64:
		return float64(v), nil
	case float32:
		return float64(v), nil
	case float64:
		return v, nil
	case bool:
		if v {
			return 1, nil
		}
		return 0, nil
	case []byte:
		return toFloat64(string(v))
	case nil:
		return 0, fmt.Errorf("couldn't convert nil to float64")
	}
	s := strings.ReplaceAll(toStringValue(in), ",", "")
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		i, ierr := strconv.ParseInt(s, 0, 64)
		if ierr != nil {
			return 0, fmt.Errorf("could not convert %q to float64: %w", s, err)
		}
		return float64(i), nil
	}
	return f, nil
}

// toJSON marshals a value to compact JSON.
func toJSON(in interface{}) (string, error) {
	b, err := json.Marshal(in)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

// toJSONPretty marshals a value to indented JSON.
func toJSONPretty(indent string, in interface{}) (string, error) {
	var b strings.Builder
	if err := marshalIndent(&b, in, indent, 0); err != nil {
		return "", err
	}
	return b.String(), nil
}

func marshalIndent(b *strings.Builder, in interface{}, indent string, depth int) error {
	s, err := json.Marshal(in)
	if err != nil {
		return err
	}
	if indent == "" {
		b.WriteString(s)
		return nil
	}
	return writeIndented(b, string(s), indent, depth)
}

func writeIndented(b *strings.Builder, s, indent string, depth int) error {
	// re-indent the JSON produced by encoding/json
	n := 0
	for _, c := range s {
		switch c {
		case '{', '[':
			n++
			b.WriteRune(c)
			b.WriteString("\n" + strings.Repeat(indent, n))
		case '}', ']':
			n--
			b.WriteString("\n" + strings.Repeat(indent, n))
			b.WriteRune(c)
		case ',':
			b.WriteRune(c)
			b.WriteString("\n" + strings.Repeat(indent, n))
		case ':':
			b.WriteString(": ")
		default:
			b.WriteRune(c)
		}
	}
	return nil
}

// isNum reports whether the value is a number, or a string that parses as one.
func isNum(in interface{}) bool {
	switch in.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:
		return true
	}
	_, err := toFloat64(in)
	return err == nil
}

// kind returns the "kind" name gomplate uses for a value.
func kind(in interface{}) string {
	switch in.(type) {
	case nil:
		return "nil"
	case bool:
		return "bool"
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return "int"
	case float32, float64:
