	}
	var key string
	var list interface{}
	if len(args) == 2 {
		k, ok := args[0].(string)
		if !ok {
			return nil, fmt.Errorf("Sort: key must be a string, got %T", args[0])
		}
		key = k
		list = args[1]
	} else {
		list = args[0]
	}
	s, err := listToSlice(list)
	if err != nil {
		return nil, err
	}
	out := make([]interface{}, len(s))
	copy(out, s)
