		a, b := out[i], out[j]
		if key != "" {
			ma, oka := a.(map[string]interface{})
			mb, okb := b.(map[string]interface{})
			if oka && okb {
				a, oka = ma[key]
				b, okb = mb[key]
				if !oka || !okb {
					return false
				}
			}
		}
		na, aok := toNumber(a)
		nb, bok := toNumber(b)
		if aok && bok {
