		}
		if itemlen == 2 {
			i, err = indexArg(1, "first")
			if err != nil {
				return nil, err
			}
			j = argReflectVal.Len()
		} else if itemlen == 3 {
			i, err = indexArg(1, "first")
			if err != nil {
