			}
		}
		if i < 0 || i >= argReflectVal.Len() {
			return nil, fmt.Errorf("slice: index %d out of range for %s", i, argReflectVal.Type())
		}
		if j < 0 || j > argReflectVal.Len() {
			return nil, fmt.Errorf("slice: index %d out of range for %s", j, argReflectVal.Type())
		}
		return argReflectVal.Slice(i, j).Interface(), nil
	case reflect.Slice:
		if argLen := argReflectVal.Len(); argLen == 0 {
			return arg, nil
		}
		if itemlen == 2 {
			i, err = indexArg(1, "first")
			if err != nil {
				return nil, err
			}
			j = argReflectVal.Len()
		} else if itemlen == 3 {
			i, err = indexArg(1, "first")
			if err != nil {
				return nil, err
			}
			j, err = indexArg(2, "second")
			if err != nil {
