			return nil, fmt.Errorf("slice: index %d out of range for %s", i, argReflectVal.Type())
		}
		if j < 0 || j > argReflectVal.Len() {
			return nil, fmt.Errorf("slice: index %d out of range for %s", j, argReflectVal.Type())
		}
		return argReflectVal.Slice(i, j).Interface(), nil
	}
}

// Has reports whether a list or map contains the given item.
func Has(in interface{}, item interface{}) (bool, error) {
	switch t := in.(type) {
	case []interface{}:
		for _, v := range t {
			if equalValue(v, item) {
				return true, nil
			}
		}
	case map[string]interface{}:
		_, ok := t[toStringValue(item)]
		return ok, nil
	}
	return false, fmt.Errorf("cannot find Has on type %s", typeName(in))
}

func typeName(in interface{}) string {
	if in == nil {
		return "<nil>"
	}
	return fmt.Sprintf("%T", in)
}

func equalValue(a, b interface{}) bool {
	return fmt.Sprintf("%v", a) == fmt.Sprintf("%v", b) && sameKind(a, b)
}

func sameKind(a, b interface{}) bool {
	ka, kb := reflect.ValueOf(a).Kind(), reflect.ValueOf(b).Kind()
	return ka == kb
}

// Index returns the item at the given index(es).
func Index(indexes ...interface{}) (interface{}, error) {
	if len(indexes) < 2 {
		return nil, fmt.Errorf("Index: wrong number of args: want at least 2, got %d", len(indexes))
	}
	item := indexes[len(indexes)-1]
	indexes = indexes[:len(indexes)-1]
	v := reflect.ValueOf(item)
	for _, i := range indexes {
		switch v.Kind() {
		case reflect.Map:
			k := reflect.ValueOf(i)
			if !k.IsValid() || !k.Type().AssignableTo(v.Type().Key()) {
				return nil, fmt.Errorf("cannot index %s with %T", v.Type(), i)
			}
			nv := v.MapIndex(k)
			if !nv.IsValid() {
				return nil, fmt.Errorf("index: key %v not found", i)
			}
			v = nv
		case reflect.Slice, reflect.Array, reflect.String:
			iv, err := toInt64(i)
			if err != nil {
				return nil, err
			}
			idx := int(iv)
			if idx < 0 || idx >= v.Len() {
				return nil, fmt.Errorf("index: index %d out of range for %s", idx, v.Type())
			}
			v = v.Index(idx)
		default:
			return nil, fmt.Errorf("cannot index %s with %T", v.Type(), i)
		}
	}
	return v.Interface(), nil
}

// Keys returns the keys of the given maps, sorted.
func Keys(in ...interface{}) ([]string, error) {
	keys := []string{}
	for _, m := range in {
		t := reflect.ValueOf(m)
		if t.Kind() != reflect.Map {
			return nil, fmt.Errorf("cannot return keys for non-map type %s", typeName(m))
		}
		for _, k := range t.MapKeys() {
			keys = append(keys, toStringValue(k.Interface()))
		}
	}
	sort.Strings(keys)
	return keys, nil
}

// Values returns the values of the given maps, ordered by key.
func Values(in ...interface{}) ([]interface{}, error) {
	vals := []interface{}{}
	for _, m := range in {
		t := reflect.ValueOf(m)
		if t.Kind() != reflect.Map {
			return nil, fmt.Errorf("cannot return values for non-map type %s", typeName(m))
		}
		keys := make([]string, 0, t.Len())
		for _, k := range t.MapKeys() {
			keys = append(keys, toStringValue(k.Interface()))
		}
		sort.Strings(keys)
		for _, k := range keys {
			vals = append(vals, t.MapIndex(reflect.ValueOf(k)).Interface())
		}
	}
	return vals, nil
}

func listToSlice(in interface{}) ([]interface{}, error) {
	switch t := in.(type) {
	case []interface{}:
		return t, nil
	case string:
		return []interface{}{}, fmt.Errorf("cannot append to string")
	}
	return nil, fmt.Errorf("cannot use %s as a list", typeName(in))
}

// Append adds a value to the end of one or more lists.
func Append(value interface{}, list ...interface{}) (interface{}, error) {
	var out []interface{}
	for _, l := range list {
		s, err := listToSlice(l)
		if err != nil {
			return nil, err
		}
		out = append(out, s...)
	}
	out = append(out, value)
	return out, nil
}

// Prepend adds a value to the front of one or more lists.
func Prepend(value interface{}, list ...interface{}) (interface{}, error) {
	out := []interface{}{value}
	for _, l := range list {
		s, err := listToSlice(l)
		if err != nil {
			return nil, err
		}
		out = append(out, s...)
	}
	return out, nil
}

// Uniq removes duplicate values from a list.
func Uniq(list interface{}) (interface{}, error) {
	s, err := listToSlice(list)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, v := range s {
		found := false
		for _, o := range out {
			if equalValue(o, v) {
				found = true
				break
			}
		}
		if !found {
			out = append(out, v)
		}
	}
	return out, nil
}

// Flatten flattens nested lists, optionally to a given depth.
func Flatten(args ...interface{}) (interface{}, error) {
	var depth int64 = -1
	var list interface{}
	switch len(args) {
	case 1:
		list = args[0]
	case 2:
		d, err := toInt64(args[0])
		if err != nil {
			return nil, err
		}
		depth = d
		list = args[1]
	default:
		return nil, fmt.Errorf("Flatten: wrong number of args: want 1 or 2, got %d", len(args))
	}
	s, err := listToSlice(list)
	if err != nil {
		return nil, err
	}
	out, err := flatten(s, depth)
	if err != nil {
		return nil, err
	}
	return out, nil
}

func flatten(in []interface{}, depth int64) ([]interface{}, error) {
	out := []interface{}{}
	for _, v := range in {
		l, ok := v.([]interface{})
		if !ok || depth == 0 {
			out = append(out, v)
			continue
		}
		d := depth
		if d > 0 {
			d--
		}
		sub, err := flatten(l, d)
		if err != nil {
			return nil, err
		}
		out = append(out, sub...)
	}
	return out, nil
}

// Reverse reverses a list.
func Reverse(list interface{}) (interface{}, error) {
	s, err := listToSlice(list)
	if err != nil {
		return nil, err
	}
	out := make([]interface{}, len(s))
	for i, v := range s {
		out[len(s)-1-i] = v
	}
	return out, nil
}

// Sort sorts a list, optionally by a key of each element.
func Sort(args ...interface{}) (interface{}, error) {
	if len(args) == 0 || len(args) > 2 {
		return nil, fmt.Errorf("Sort: wrong number of args: want 1 or 2, got %d", len(args))
	}
	var key string
	var list interface{}
	if len(args) == 2 {
		k, ok := args[0].(string)
		if !ok {
			return nil, fmt.Errorf("Sort: key must be a string, got %T", args[0])
		}
		key = k
		list = args[1]
	} else {
		list = args[0]
	}
	s, err := listToSlice(list)
	if err != nil {
		return nil, err
	}
	out := make([]interface{}, len(s))
	copy(out, s)
	sort.SliceStable(out, func(i, j int) bool {
		a, b := out[i], out[j]
		if key != "" {
			ma, oka := a.(map[string]interface{})
			mb, okb := b.(map[string]interface{})
			if oka && okb {
				a, oka = ma[key]
				b, okb = mb[key]
				if !oka || !okb {
					return false
				}
			}
		}
		na, aok := toNumber(a)
		nb, bok := toNumber(b)
		if aok && bok {
			return na < nb
		}
		return toStringValue(a) < toStringValue(b)
	})
	return out, nil
}

func toNumber(in interface{}) (float64, bool) {
	f, err := toFloat64(in)
	if err != nil {
		return 0, false
	}
	return f, true
}

// Merge merges one or more maps into the first argument.
func Merge(dst interface{}, srcs ...interface{}) (map[string]interface{}, error) {
	d, ok := dst.(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("expected a map, got %s", typeName(dst))
	}
	for _, src := range srcs {
		s, ok := src.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("expected a map, got %s", typeName(src))
		}
		for k, v := range s {
			if _, ok := d[k]; !ok {
				d[k] = v
				continue
			}
			if dm, ok := d[k].(map[string]interface{}); ok {
				if sm, ok := v.(map[string]interface{}); ok {
					nm, err := Merge(map[string]interface{}{}, dm, sm)
					if err != nil {
						return nil, err
					}
					d[k] = nm
					continue
				}
			}
		}
	}
	return d, nil
}

// Pick returns a new map with only the given keys.
func Pick(args ...interface{}) (map[string]interface{}, error) {
	if len(args) < 1 {
		return nil, fmt.Errorf("Pick: wrong number of args")
	}
	m, ok := args[len(args)-1].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("expected a map, got %s", typeName(args[len(args)-1]))
	}
	keys, err := keyList(args[:len(args)-1])
	if err != nil {
		return nil, err
	}
	out := map[string]interface{}{}
	for _, k := range keys {
		if v, ok := m[k]; ok {
			out[k] = v
		}
	}
	return out, nil
}

// Omit returns a new map without the given keys.
func Omit(args ...interface{}) (map[string]interface{}, error) {
	if len(args) < 1 {
		return nil, fmt.Errorf("Omit: wrong number of args")
	}
	m, ok := args[len(args)-1].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("expected a map, got %s", typeName(args[len(args)-1]))
	}
	keys, err := keyList(args[:len(args)-1])
	if err != nil {
		return nil, err
	}
	out := map[string]interface{}{}
	for k, v := range m {
		skip := false
		for _, k2 := range keys {
			if k == k2 {
				skip = true
				break
			}
		}
		if !skip {
			out[k] = v
		}
	}
	return out, nil
}

func keyList(args []interface{}) ([]string, error) {
	keys := []string{}
	for _, a := range args {
		switch t := a.(type) {
		case string:
			keys = append(keys, t)
		case []interface{}:
			for _, v := range t {
				keys = append(keys, toStringValue(v))
			}
		default:
			keys = append(keys, toStringValue(a))
		}
	}
	return keys, nil
}

// Set sets a key in a map.
func Set(args ...interface{}) (map[string]interface{}, error) {
	if len(args) != 3 {
		return nil, fmt.Errorf("Set: wrong number of args: want 3, got %d", len(args))
	}
	m, ok := args[2].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("expected a map, got %s", typeName(args[2]))
	}
	m[toStringValue(args[0])] = args[1]
	return m, nil
}

// Unset removes a key from a map.
func Unset(args ...interface{}) (map[string]interface{}, error) {
	if len(args) != 2 {
		return nil, fmt.Errorf("Unset: wrong number of args: want 2, got %d", len(args))
	}
	m, ok := args[1].(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("expected a map, got %s", typeName(args[1]))
	}
	delete(m, toStringValue(args[0]))
	return m, nil
}

