		}
		if _, ok := v.(int64); ok {
			continue
		}
		allInts = false
		break
	}
	if allInts {
		var sum int64
		for _, v := range n {
			i, err := toInt64(v)
			if err != nil {
				return nil, err
			}
			sum += i
		}
		return sum, nil
	}
	var sum float64
	for _, v := range n {
