// Add sums its arguments.
func (mathFuncs) Add(n ...interface{}) (interface{}, error) {
	allInts := true
	for _, v := range n {
		if _, ok := v.(int); ok {
			continue
		}
		if _, ok := v.(int64); ok {
			continue
		}
		allInts = false
		break
	}
	if allInts {
		var sum int64
		for _, v := range n {
			i, err := toInt64(v)
			if err != nil {
				return nil, err
			}
			sum += i
		}
		return sum, nil
	}
	var sum float64
	for _, v := range n {
		f, err := toFloat64(v)
		if err != nil {
			return nil, err
		}
		sum += f
	}
	return sum, nil
}

// Sub subtracts subsequent arguments from the first.
func (mathFuncs) Sub(n ...interface{}) (interface{}, error) {
	if len(n) == 0 {
		return nil, fmt.Errorf("Sub: wrong number of args")
	}
	allInts := true
	for _, v := range n {
		switch v.(type) {
		case int, int64:
		default:
			allInts = false
		}
	}
	if allInts {
		s, err := toInt64(n[0])
		if err != nil {
			return nil, err
		}
		for _, v := range n[1:] {
			i, err := toInt64(v)
			if err != nil {
				return nil, err
			}
			s -= i
		}
		return s, nil
	}
	s, err := toFloat64(n[0])
	if err != nil {
		return nil, err
	}
	for _, v := range n[1:] {
		f, err := toFloat64(v)
		if err != nil {
			return nil, err
		}
		s -= f
	}
	return s, nil
}

// Mul multiplies its arguments.
func (mathFuncs) Mul(n ...interface{}) (interface{}, error) {
	allInts := true
	for _, v := range n {
		switch v.(type) {
		case int, int64:
		default:
			allInts = false
		}
	}
	if allInts {
		var p int64 = 1
		for _, v := range n {
