	s, ok := num.(string)
	if !ok {
		return false
	}
	f, err := toFloat64(s)
	if err != nil {
		return false
	}
	// a string that parses as an integer is not a float
	if _, err := toInt64(s); err == nil {
		return false
	}
	_ = f
	return true
}

