// Seq returns a sequence of integers.
func (mathFuncs) Seq(args ...interface{}) ([]int64, error) {
	var start, end, step int64
	switch len(args) {
	case 1:
		e, err := toInt64(args[0])
		if err != nil {
			return nil, err
		}
		start, end, step = 1, e, 1
	case 2:
		s, err := toInt64(args[0])
		if err != nil {
			return nil, err
		}
		e, err := toInt64(args[1])
		if err != nil {
			return nil, err
		}
		start, end, step = s, e, 1
	case 3:
		s, err := toInt64(args[0])
		if err != nil {
			return nil, err
		}
		e, err := toInt64(args[1])
		if err != nil {
			return nil, err
		}
		st, err := toInt64(args[2])
		if err != nil {
			return nil, err
		}
		start, end, step = s, e, st
	default:
		return nil, fmt.Errorf("Seq: wrong number of args: want 1-3, got %d", len(args))
	}
	return seq(start, end, step), nil
}

func seq(start, end, step int64) []int64 {
	if step == 0 {
		return []int64{}
	}
	if end < start && step > 0 {
		step = -step
	}
	if end > start && step < 0 {
		step = -step
	}
	end -= (end - start) % step
	out := []int64{start}
	last := start
	for last != end {
		last = out[len(out)-1] + step
		out = append(out, last)
	}
	return out
}

