// title capitalizes the first letter of each word, like strings.Title.
func title(s string) string {
	var prev rune = ' '
	var b strings.Builder
	for _, r := range s {
		if isSeparator(prev) {
			r = unicode.ToTitle(r)
		}
		prev = r
		b.WriteRune(r)
	}
	return b.String()
}

func isSeparator(r rune) bool {
	if r <= 0x7F {
		switch {
		case '0' <= r && r <= '9':
			return false
		case 'a' <= r && r <= 'z':
			return false
		case 'A' <= r && r <= 'Z':
			return false
		case r == '_':
			return false
		}
		return true
	}
	switch {
	case unicode.IsLetter(r):
		return false
	case unicode.IsDigit(r):
		return false
	}
	return true
}
