	if err != nil {
		return "", err
	}
	s, err := asString(input)
	if err != nil {
		return "", err
	}
	return strings.Repeat(s, int(n)), nil
}

// ReplaceAll replaces all occurrences of old with new.
func (stringsFuncs) ReplaceAll(old, new, input interface{}) (string, error) {
	s, err := asString(input)
	if err != nil {
		return "", err
	}
	o, err := asString(old)
	if err != nil {
		return "", err
	}
	nw, err := asString(new)
	if err != nil {
		return "", err
	}
	return strings.ReplaceAll(s, o, nw), nil
}

// RuneCount returns the number of runes in the input.
func (stringsFuncs) RuneCount(input interface{}) (int, error) {
	s, err := asString(input)
	if err != nil {
		return 0, err
	}
	return len([]rune(s)), nil
}

// WordWrap wraps text at the given width.
func (stringsFuncs) WordWrap(args ...interface{}) (string, error) {
	var width int64 = 80
	var lbseq = "\n"
	var input string
	switch len(args) {
	case 1:
		s, err := asString(args[0])
		if err != nil {
			return "", err
		}
		input = s
	case 2:
		w, err := toInt64(args[0])
		if err != nil {
			return "", err
		}
		width = w
		s, err := asString(args[1])
		if err != nil {
			return "", err
		}
		input = s
	case 3:
		w, err := toInt64(args[0])
		if err != nil {
			return "", err
		}
		width = w
		s, err := asString(args[1])
		if err != nil {
			return "", err
		}
		lbseq = s
		in, err := asString(args[2])
		if err != nil {
			return "", err
		}
		input = in
	default:
		return "", fmt.Errorf("WordWrap: wrong number of args: want 1-3, got %d", len(args))
	}
	return wordWrap(input, int(width), lbseq), nil
}

func wordWrap(in string, width int, lbseq string) string {
	if width <= 0 {
		return in
	}
	words := strings.Fields(in)
	if len(words) == 0 {
		return in
	}
	var out strings.Builder
	lineLen := 0
	for i, w := range words {
		if i > 0 {
			if lineLen+1+len(w) > width {
				out.WriteString(lbseq)
				lineLen = 0
			} else {
				out.WriteString(" ")
				lineLen++
			}
		}
		out.WriteString(w)
		lineLen += len(w)
	}
	out.WriteString("\n")
	return out.String()
}

var wordSplitRE = regexp.MustCompile(`[^\p{L}\p{N}_]+`)
var snakeWordRE = regexp.MustCompile(`[^\p{L}\p{N}]+`)

// CamelCase converts the input to CamelCase.
func (stringsFuncs) CamelCase(in interface{}) (string, error) {
	s, err := asString(in)
	if err != nil {
		return "", err
	}
	return camelize(s), nil
}

func camelize(in string) string {
	in = strings.TrimSpace(in)
	parts := wordSplitRE.Split(in, -1)
	var out strings.Builder
	for i, p := range parts {
		if p == "" {
			continue
		}
		out.WriteString(camelizeWord(p, i == 0))
	}
	return strings.ReplaceAll(out.String(), "_", "")
}

func camelizeWord(w string, first bool) string {
	runes := []rune(strings.ToLower(w))
	orig := []rune(w)
	if len(runes) == 0 {
		return ""
	}
	if first {
		if unicode.IsLetter(runes[0]) {
			runes[0] = orig[0]
		} else {
			for i := range runes {
				if unicode.IsLetter(runes[i]) {
					runes[i] = unicode.ToUpper(runes[i])
					break
				}
			}
		}
	} else {
		for i := range runes {
			if unicode.IsLetter(runes[i]) {
				runes[i] = unicode.ToUpper(runes[i])
				break
			}
		}
	}
	return string(runes)
}

func caseDelimited(in string, delim rune) string {
	in = strings.TrimSpace(in)
	parts := snakeWordRE.Split(in, -1)
	var out []string
	for i, p := range parts {
		if p == "" {
			continue
		}
		runes := []rune(strings.ToLower(p))
		if i == 0 && len(runes) > 0 {
			orig := []rune(p)
			if unicode.IsLetter(runes[0]) {
				runes[0] = orig[0]
			}
		}
		out = append(out, string(runes))
	}
	return strings.Join(out, string(delim))
}

// SnakeCase converts the input to snake_case.
func (stringsFuncs) SnakeCase(in interface{}) (string, error) {
	s, err := asString(in)
	if err != nil {
		return "", err
	}
	return caseDelimited(s, '_'), nil
}

// KebabCase converts the input to kebab-case.
func (stringsFuncs) KebabCase(in interface{}) (string, error) {
	s, err := asString(in)
	if err != nil {
		return "", err
	}
	return caseDelimited(s, '-'), nil
}

var slugRE = regexp.MustCompile(`[^\p{L}\p{N}_\-]+`)

// Slug converts the input to a URL-safe slug.
func (stringsFuncs) Slug(in interface{}) (string, error) {
	s, err := asString(in)
	if err != nil {
		return "", err
	}
	s = transliterate(s)
	s = strings.ToLower(s)
	s = slugRE.ReplaceAllString(s, "-")
	return strings.Trim(s, "-"), nil
}

// top-level aliases

// Title is the top-level title function.
func Title(in interface{}) (string, error) { return stringsNS().Title(in) }

// ToUpper is the top-level toUpper function.
func ToUpper(in interface{}) (string, error) { return stringsNS().ToUpper(in) }

// ToLower is the top-level toLower function.
func ToLower(in interface{}) (string, error) { return stringsNS().ToLower(in) }

// TrimSpace is the top-level trimSpace function.
func TrimSpace(in interface{}) (string, error) { return stringsNS().TrimSpace(in) }

// ReplaceAll is the top-level replaceAll function.
func ReplaceAll(old, new, input interface{}) (string, error) {
	return stringsNS().ReplaceAll(old, new, input)
}

// Quote is the top-level quote function.
func Quote(in interface{}) string { return stringsNS().Quote(in) }

// Squote is the top-level squote function.
func Squote(in interface{}) string { return stringsNS().Squote(in) }

// ShellQuote is the top-level shellQuote function.
func ShellQuote(in interface{}) string { return stringsNS().ShellQuote(in) }

// Indent is the top-level indent function.
func Indent(args ...interface{}) (string, error) { return stringsNS().Indent(args...) }

// Slug is the top-level slug function.
func Slug(in interface{}) (string, error) { return stringsNS().Slug(in) }

// title capitalizes the first letter of each word, like strings.Title.
func title(s string) string {
	var prev rune = ' '
	var b strings.Builder
	for _, r := range s {
		if isSeparator(prev) {
			r = unicode.ToTitle(r)
		}
		prev = r
		b.WriteRune(r)
	}
	return b.String()
}

func isSeparator(r rune) bool {
	if r <= 0x7F {
		switch {
		case '0' <= r && r <= '9':
			return false
		case 'a' <= r && r <= 'z':
			return false
		case 'A' <= r && r <= 'Z':
			return false
		case r == '_':
			return false
		}
		return true
	}
	switch {
	case unicode.IsLetter(r):
		return false
	case unicode.IsDigit(r):
		return false
	}
	return true
}
