var asciiChars = "!\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~"

// ASCII returns a random string of ASCII printable characters.
func (randomFuncs) ASCII(count interface{}) (string, error) {
	n, err := toInt64(count)
	if err != nil {
