	}
	return string(b), nil
}

// Alpha returns a random string of letters.
func (randomFuncs) Alpha(count interface{}) (string, error) {
	n, err := toInt64(count)
	if err != nil {
		return "", err
	}
	b := make([]byte, n)
	for i := range b {
