package funcs

import (
	"regexp"
)

// regexpFuncs is the regexp namespace.
type regexpFuncs struct{}

func regexpNS() regexpFuncs { return regexpFuncs{} }

func compile(expr interface{}) (*regexp.Regexp, error) {
	s, err := asString(expr)
	if err != nil {
		return nil, err
	}
	return regexp.Compile(s)
}

// Find returns the first match of the expression in the input.
func (regexpFuncs) Find(expr, input interface{}) (string, error) {
	re, err := compile(expr)
	if err != nil {
		return "", err
	}
	s, err := asString(input)
	if err != nil {
		return "", err
	}
	return re.FindString(s), nil
}

// FindAll returns all matches of the expression in the input.
func (regexpFuncs) FindAll(args ...interface{}) ([]string, error) {
	var expr, input interface{}
	var n = -1
	switch len(args) {
	case 2:
		expr, input = args[0], args[1]
	case 3:
		expr = args[0]
		i, err := toInt64(args[1])
		if err != nil {
			return nil, err
		}
		n = int(i)
		input = args[2]
	default:
		return nil, errWrongArgs("FindAll", len(args))
