	if err != nil {
		return nil, err
	}
	s, err := asString(input)
	if err != nil {
		return nil, err
	}
	return re.FindAllString(s, n), nil
}

// Match reports whether the expression matches the input.
func (regexpFuncs) Match(expr, input interface{}) (bool, error) {
	re, err := compile(expr)
	if err != nil {
		return false, err
	}
	s, err := asString(input)
	if err != nil {
