func (v semver) Major() uint64 { return v.major }

// Minor returns the minor version.
func (v semver) Minor() uint64 { return v.minor }

// Patch returns the patch version.
func (v semver) Patch() uint64 { return v.patch }

// Prerelease returns the pre-release version.
func (v semver) Prerelease() string { return v.pre }

// SetPrerelease returns a copy with a new pre-release version.
func (v semver) SetPrerelease(pre string) semver {
	v.pre = pre
	return v
}

// SetMetadata returns a copy with new build metadata.
func (v semver) SetMetadata(m string) semver {
	v.build = m
	return v
}

// IsPrerelease reports whether the version is a pre-release.
func (v semver) IsPrerelease() bool { return v.pre != "" }

// Compare compares two versions.
func (v semver) Compare(o semver) int {
	if v.major != o.major {
		if v.major < o.major {
			return -1
		}
		return 1
	}
	if v.minor != o.minor {
		if v.minor < o.minor {
			return -1
		}
		return 1
	}
	if v.patch != o.patch {
		if v.patch < o.patch {
			return -1
		}
		return 1
	}
	if v.pre == "" && o.pre != "" {
		return 1
	}
	if v.pre != "" && o.pre == "" {
		return -1
	}
	return strings.Compare(v.pre, o.pre)
}

// CheckConstraint reports whether the version satisfies the constraint.
func (semverFuncs) CheckConstraint(constraint, version interface{}) (bool, error) {
	c, err := asString(constraint)
	if err != nil {
		return false, err
	}
	v, err := asString(version)
	if err != nil {
		return false, err
	}
	sv, err := parseSemver(v)
	if err != nil {
		return false, err
	}
	return checkConstraint(c, sv)
}

func checkConstraint(c string, v *semver) (bool, error) {
	parts := strings.Split(c, ",")
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		op := ""
		rest := p
		for _, o := range []string{">=", "<=", "!=", "~>", "~", "==", ">", "<", "="} {
			if strings.HasPrefix(p, o) {
				op = o
				rest = strings.TrimSpace(strings.TrimPrefix(p, o))
				break
			}
		}
		if op == "" {
			op = "="
			rest = p
		}
		cv, err := parseSemver(rest)
		if err != nil {
			return false, err
		}
		cmp := v.Compare(cv)
		var ok bool
		switch op {
		case ">":
			ok = cmp > 0
		case ">=":
			ok = cmp >= 0
		case "<":
			ok = cmp < 0
		case "<=":
			ok = cmp <= 0
		case "=", "==":
			ok = cmp == 0
		case "!=":
			ok = cmp != 0
		case "~", "~>":
			ok = cmp >= 0 && v.major == cv.major && v.minor == cv.minor
		}
		if !ok {
			return false, nil
		}
	}
	return true, nil
}

// Semver is the top-level semver function.
func Semver(in interface{}) (*semver, error) { return semverNS().Semver(in) }

// CheckConstraint is the top-level checkConstraint function.
func CheckConstraint(constraint, version interface{}) (bool, error) {
	return semverNS().CheckConstraint(constraint, version)
}
