package funcs

import (
	"context"
	"fmt"
	"math/big"
	"net"
	"net/netip"
	"slices"
	"strings"
)

// netFuncs is the net namespace.
type netFuncs struct{}

func netNS() netFuncs { return netFuncs{} }

// LookupIP returns the first IPv4 address for the name.
func (netFuncs) LookupIP(name string) (string, error) {
	ips, err := netFuncs{}.LookupIPs(name)
	if err != nil {
		return "", err
	}
	if len(ips) == 0 {
		return "", nil
	}
	return ips[0], nil
}

// LookupIPs returns the IPv4 addresses for the name.
func (netFuncs) LookupIPs(name string) ([]string, error) {
	resolver := &net.Resolver{}
	srcIPs, err := resolver.LookupIPAddr(context.Background(), name)
	if err != nil {
		return nil, err
	}
	var ips []string
	for _, v := range srcIPs {
		if v.IP.To4() != nil {
			s := v.IP.String()
			if !slices.Contains(ips, s) {
				ips = append(ips, s)
			}
		}
	}
	return ips, nil
}

// LookupCNAME returns the canonical name for the name.
func (netFuncs) LookupCNAME(name string) (string, error) {
	resolver := &net.Resolver{}
	return resolver.LookupCNAME(context.Background(), name)
}

// LookupTXT returns the TXT records for the name.
func (netFuncs) LookupTXT(name string) ([]string, error) {
	resolver := &net.Resolver{}
	return resolver.LookupTXT(context.Background(), name)
}

// LookupSRV returns the first SRV record for the name.
func (netFuncs) LookupSRV(name string) (*net.SRV, error) {
	srvs, err := netFuncs{}.LookupSRVs(name)
	if err != nil {
		return nil, err
	}
	return srvs[0], nil
}

// LookupSRVs returns the SRV records for the name.
func (netFuncs) LookupSRVs(name string) ([]*net.SRV, error) {
	resolver := &net.Resolver{}
	_, addrs, err := resolver.LookupSRV(context.Background(), "", "", name)
	if err != nil {
		return nil, err
	}
	return addrs, nil
}

// ParseAddr parses an IP address.
func (netFuncs) ParseAddr(addr string) (*addrObj, error) {
	ip, err := netip.ParseAddr(addr)
	if err != nil {
		return nil, err
	}
	return &addrObj{ip: ip}, nil
}

// ParsePrefix parses a CIDR prefix.
func (netFuncs) ParsePrefix(p string) (*prefixObj, error) {
	pp, err := netip.ParsePrefix(p)
	if err != nil {
		return nil, err
	}
	return &prefixObj{p: pp}, nil
}

// ParseRange parses an IP range.
func (netFuncs) ParseRange(r string) (*rangeObj, error) {
	parts := strings.SplitN(r, "-", 2)
	if len(parts) != 2 {
		return nil, fmt.Errorf("invalid range: %s", r)
	}
	from, err := netip.ParseAddr(strings.TrimSpace(parts[0]))
	if err != nil {
		return nil, err
	}
	to, err := netip.ParseAddr(strings.TrimSpace(parts[1]))
	if err != nil {
		return nil, err
	}
	return &rangeObj{from: from, to: to}, nil
}

// CIDRHost returns the host at the given index in the prefix.
func (netFuncs) CIDRHost(hostnum interface{}, prefix string) (string, error) {
	n, err := toInt64(hostnum)
	if err != nil {
		return "", err
	}
	pp, err := netip.ParsePrefix(prefix)
	if err != nil {
		return "", err
	}
	bits := pp.Addr().BitLen()
	hostBits := bits - pp.Bits()
	if n >= int64(1)<<uint(hostBits) {
		return "", fmt.Errorf("prefix of %d bits does not accommodate over %d hosts", pp.Bits(), n)
	}
	base := prefixToBigInt(pp.Masked().Addr())
	host := base.Add(base, big.NewInt(n))
	return bigToAddr(host, bits).String(), nil
}

// CIDRNetmask returns the netmask of the prefix.
func (netFuncs) CIDRNetmask(prefix string) (string, error) {
	pp, err := netip.ParsePrefix(prefix)
	if err != nil {
		return "", err
	}
	bits := pp.Addr().BitLen()
	mask := big.NewInt(0)
	mask.Lsh(big.NewInt(1), uint(bits))
	mask.Sub(mask, big.NewInt(1))
	mask.Rsh(mask, uint(bits-pp.Bits()))
	mask.Lsh(mask, uint(hostBits(pp)))
	return bigToAddr(mask, bits).String(), nil
}

func hostBits(p netip.Prefix) int {
	return p.Addr().BitLen() - p.Bits()
}

// CIDRSubnets splits the prefix into subnets of the given size.
func (netFuncs) CIDRSubnets(newbits interface{}, prefix string) ([]string, error) {
	n, err := toInt64(newbits)
	if err != nil {
		return nil, err
	}
	pp, err := netip.ParsePrefix(prefix)
	if err != nil {
		return nil, err
	}
	newBits := pp.Bits() + int(n)
	if newBits > pp.Addr().BitLen() {
		return nil, fmt.Errorf("not enough space to expand prefix")
	}
	out := []string{}
	s := pp.Masked()
	for i := 0; i < 1<<uint(n); i++ {
		b := prefixToBigInt(s.Addr())
		b.Add(b, big.NewInt(int64(i)<<(pp.Addr().BitLen()-newBits)))
		out = append(out, netip.PrefixFrom(bigToAddr(b, pp.Addr().BitLen()), newBits).String())
	}
	return out, nil
}

// CIDRSubnetSizes splits the prefix into subnets of the given sizes.
func (netFuncs) CIDRSubnetSizes(args ...interface{}) ([]string, error) {
	if len(args) < 1 {
		return nil, fmt.Errorf("wrong number of args")
	}
	sizes := make([]int64, 0, len(args)-1)
	for _, a := range args[:len(args)-1] {
