	}
	pp, err := netip.ParsePrefix(prefix)
	if err != nil {
		return nil, err
	}
	out := []string{}
	base := prefixToBigInt(pp.Masked().Addr())
	bits := pp.Addr().BitLen()
	offset := int64(0)
	for _, sz := range sizes {
		newBits := int(pp.Bits()) + int(sz)
		b := big.NewInt(0)
		b.Add(base, big.NewInt(offset))
		out = append(out, netip.PrefixFrom(bigToAddr(b, bits), newBits).String())
		offset += int64(1) << uint(bits-newBits)
	}
	return out, nil
}

func prefixToBigInt(a netip.Addr) *big.Int {
	b := a.As16()
	return new(big.Int).SetBytes(b[:])
}

func bigToAddr(b *big.Int, bits int) netip.Addr {
	bs := b.Bytes()
	buf := make([]byte, 16)
	copy(buf[16-len(bs):], bs)
	if bits == 32 {
		ip, _ := netip.AddrFromSlice(buf[12:])
		return ip
	}
	ip, _ := netip.AddrFromSlice(buf)
	return ip
}

// addrObj wraps an IP address with attributes.
type addrObj struct {
	ip netip.Addr
}

// String returns the string form of the address.
func (a addrObj) String() string { return a.ip.String() }

// IsPrivate reports whether the address is in a private range.
func (a addrObj) IsPrivate() bool { return a.ip.IsPrivate() }

// IsGlobalUnicast reports whether the address is a global unicast address.
func (a addrObj) IsGlobalUnicast() bool { return a.ip.IsGlobalUnicast() }

// IsLoopback reports whether the address is a loopback address.
func (a addrObj) IsLoopback() bool { return a.ip.IsLoopback() }

// IsMulticast reports whether the address is a multicast address.
func (a addrObj) IsMulticast() bool { return a.ip.IsMulticast() }

// IsLinkLocalUnicast reports whether the address is link-local.
func (a addrObj) IsLinkLocalUnicast() bool { return a.ip.IsLinkLocalUnicast() }

// IsUnspecified reports whether the address is unspecified.
func (a addrObj) IsUnspecified() bool { return a.ip.IsUnspecified() }

// To4 returns the address as an IPv4 address, or nil.
func (a addrObj) To4() *addrObj {
	if a.ip.Is4() {
		return &addrObj{ip: a.ip}
	}
	return nil
}

// Prefix returns the prefix of the given length containing the address.
func (a addrObj) Prefix(bits interface{}) (string, error) {
	n, err := toInt64(bits)
	if err != nil {
		return "", err
	}
	return netip.PrefixFrom(a.ip, int(n)).String(), nil
}

// prefixObj wraps an IP prefix.
type prefixObj struct {
	p netip.Prefix
}

// String returns the string form of the prefix.
func (p prefixObj) String() string { return p.p.String() }

// Contains reports whether the address is within the prefix.
func (p prefixObj) Contains(a addrObj) bool { return p.p.Contains(a.ip) }

// Range returns the range of addresses in the prefix.
func (p prefixObj) Range() string {
	from := p.p.Addr()
	last := prefixToBigInt(from)
	last.Add(last, big.NewInt(int64(hosts(p.p))-1))
	return from.String() + "-" + bigToAddr(last, p.p.Addr().BitLen()).String()
}

// Bits returns the number of bits in the prefix.
func (p prefixObj) Bits() int { return p.p.Bits() }

func hosts(p netip.Prefix) int64 {
	bits := p.Addr().BitLen() - p.Bits()
	if bits >= 64 {
		return 1<<63 - 1
	}
	return int64(1) << uint(bits)
}

// To returns the last address in the prefix.
func (p prefixObj) To() string {
	last := prefixToBigInt(p.p.Addr())
	last.Add(last, big.NewInt(int64(hosts(p.p))-1))
	return bigToAddr(last, p.p.Addr().BitLen()).String()
}

// From returns the first address in the prefix.
func (p prefixObj) From() string { return p.p.Addr().String() }

// Netmask returns the netmask of the prefix.
func (p prefixObj) Netmask() string { return netNS().CIDRNetmask(p.p.String()) }

// rangeObj wraps an IP range.
type rangeObj struct {
	from, to netip.Addr
}

// String returns the string form of the range.
func (r rangeObj) String() string { return r.from.String() + "-" + r.to.String() }

// From returns the first address in the range.
func (r rangeObj) From() string { return r.from.String() }

// To returns the last address in the range.
func (r rangeObj) To() string { return r.to.String() }

// Contains reports whether the address is within the range.
func (r rangeObj) Contains(a addrObj) bool {
	f := prefixToBigInt(r.from)
	t := prefixToBigInt(r.to)
	v := prefixToBigInt(a.ip)
	return v.Cmp(f) >= 0 && v.Cmp(t) <= 0
}

// Prefixes returns the CIDR prefixes covering the range.
func (r rangeObj) Prefixes() ([]string, error) {
	out := []string{}
	f := prefixToBigInt(r.from)
	t := prefixToBigInt(r.to)
	bits := r.from.BitLen()
	cur := new(big.Int).Set(f)
	// find the largest prefixes covering the range, smallest-first
	for size := 0; size <= bits; size++ {
		step := new(big.Int).Lsh(big.NewInt(1), uint(bits-size))
		mask := new(big.Int).Lsh(big.NewInt(1), uint(bits-size))
		mask.Sub(mask, big.NewInt(1))
		tmp := new(big.Int).And(cur, new(big.Int).Xor(big.NewInt(-1), mask))
		end := new(big.Int).Add(tmp, new(big.Int).Sub(step, big.NewInt(1)))
		if end.Cmp(t) <= 0 && tmp.Cmp(cur) >= 0 && tmp.Cmp(cur) == 0 {
			out = append(out, netip.PrefixFrom(bigToAddr(tmp, bits), size).String())
		}
	}
	_ = cur
	return out, nil
}
