// Now returns the current time.
func (timeFuncs) Now() time.Time { return time.Now() }

// Parse parses a timestamp with the given layout.
func (timeFuncs) Parse(layout, timestamp interface{}) (time.Time, error) {
	l, err := asString(layout)
	if err != nil {
		return time.Time{}, err
	}
	t, err := asString(timestamp)
	if err != nil {
		return time.Time{}, err
	}
	return time.Parse(l, t)
}

// ParseDuration parses a duration string.
func (timeFuncs) ParseDuration(duration interface{}) (time.Duration, error) {
