	}
	return time.ParseDuration(s)
}

// ParseLocal parses a timestamp in the local timezone.
func (timeFuncs) ParseLocal(layout, timestamp interface{}) (time.Time, error) {
	l, err := asString(layout)
	if err != nil {
		return time.Time{}, err
	}
	t, err := asString(timestamp)
	if err != nil {
		return time.Time{}, err
	}
	return time.ParseInLocation(l, t, time.Local)
}

// ParseInLocation parses a timestamp in the given location.
func (timeFuncs) ParseInLocation(layout, location, timestamp interface{}) (time.Time, error) {
	l, err := asString(layout)
	if err != nil {
		return time.Time{}, err
	}
	t, err := asString(timestamp)
	if err != nil {
		return time.Time{}, err
	}
	loc, err := asString(location)
	if err != nil {
		return time.Time{}, err
	}
	zone, err := time.LoadLocation(loc)
	if err != nil {
