func (timeFuncs) Until(t time.Time) time.Duration { return time.Until(t) }

// Unix returns the time for the given unix timestamp.
func (timeFuncs) Unix(v interface{}) (time.Time, error) {
	switch t := v.(type) {
	case int:
		return time.Unix(int64(t), 0), nil
	case int64:
		return time.Unix(t, 0), nil
	case float64:
		return time.Unix(int64(t), int64((t-float64(int64(t)))*1e9)), nil
	case string:
		if i, err := strconv.ParseInt(t, 10, 64); err == nil {
			return time.Unix(i, 0), nil
		}
		f, err := strconv.ParseFloat(t, 64)
		if err != nil {
			return time.Time{}, err
		}
		return time.Unix(int64(f), int64((f-float64(int64(f)))*1e9)), nil
	}
	i, err := toInt64(v)
	if err != nil {
		return time.Time{}, err
	}
	return time.Unix(i, 0), nil
}

