func (timeFuncs) Hour(v interface{}) (time.Duration, error) { return durMult(v, time.Hour) }

// Minute returns a Duration of n minutes.
func (timeFuncs) Minute(v interface{}) (time.Duration, error) { return durMult(v, time.Minute) }

// Second returns a Duration of n seconds.
func (timeFuncs) Second(v interface{}) (time.Duration, error) { return durMult(v, time.Second) }

// Millisecond returns a Duration of n milliseconds.
func (timeFuncs) Millisecond(v interface{}) (time.Duration, error) {
	return durMult(v, time.Millisecond)
}

// Microsecond returns a Duration of n microseconds.
func (timeFuncs) Microsecond(v interface{}) (time.Duration, error) {
	return durMult(v, time.Microsecond)
}

// Nanosecond returns a Duration of n nanoseconds.
func (timeFuncs) Nanosecond(v interface{}) (time.Duration, error) { return durMult(v, 1) }

func durMult(v interface{}, unit time.Duration) (time.Duration, error) {
	switch t := v.(type) {
	case int:
		return time.Duration(t) * unit, nil
	case int64:
		return time.Duration(t) * unit, nil
	case float64:
		return time.Duration(t * float64(unit)), nil
	case string:
		if i, err := strconv.ParseInt(t, 10, 64); err == nil {
			return time.Duration(i) * unit, nil
		}
		f, err := strconv.ParseFloat(t, 64)
		if err != nil {
			return 0, err
		}
		return time.Duration(f * float64(unit)), nil
	}
	i, err := toInt64(v)
	if err != nil {
		return 0, err
	}
	return time.Duration(i) * unit, nil
}

