// EncryptAES encrypts the input with AES-CBC.
func (cryptoFuncs) EncryptAES(args ...interface{}) ([]byte, error) {
	key, bits, input, err := aesArgs(args)
	if err != nil {
		return nil, err
	}
	block, err := aes.NewCipher(deriveKey(key, bits))
	if err != nil {
		return nil, err
	}
	iv := make([]byte, block.BlockSize())
	if _, err := rand.Read(iv); err != nil {
		return nil, err
	}
	data := pkcs7Pad([]byte(input), block.BlockSize())
	out := make([]byte, len(iv)+len(data))
	copy(out, iv)
	cipher.NewCBCEncrypter(block, iv).CryptBlocks(out[len(iv):], data)
	return out, nil
}

// DecryptAES decrypts AES-CBC encrypted data.
func (cryptoFuncs) DecryptAES(args ...interface{}) (string, error) {
	b, err := cryptoFuncs{}.DecryptAESBytes(args...)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

// DecryptAESBytes decrypts AES-CBC encrypted data to bytes.
func (cryptoFuncs) DecryptAESBytes(args ...interface{}) ([]byte, error) {
	key, bits, input, err := aesArgs(args)
	if err != nil {
		return nil, err
	}
	block, err := aes.NewCipher(deriveKey(key, bits))
	if err != nil {
		return nil, err
	}
	data := []byte(input)
	if len(data) < block.BlockSize() || len(data)%block.BlockSize() != 0 {
		return nil, fmt.Errorf("input is not a multiple of the block size")
	}
	iv := data[:block.BlockSize()]
	data = data[block.BlockSize():]
	out := make([]byte, len(data))
	cipher.NewCBCDecrypter(block, iv).CryptBlocks(out, data)
	return pkcs7Unpad(out, block.BlockSize())
}

func aesArgs(args []interface{}) (string, int, string, error) {
	var key, input string
	bits := 256
	switch len(args) {
	case 2:
		k, err := asString(args[0])
		if err != nil {
			return "", 0, "", err
		}
		key = k
		i, err := asString(args[1])
		if err != nil {
			return "", 0, "", err
		}
		input = i
	case 3:
		k, err := asString(args[0])
		if err != nil {
			return "", 0, "", err
		}
		key = k
		b, err := toInt64(args[1])
		if err != nil {
			return "", 0, "", fmt.Errorf("keyBits must be an integer: %w", err)
		}
		bits = int(b)
		i, err := asString(args[2])
		if err != nil {
			return "", 0, "", err
		}
		input = i
	default:
		return "", 0, "", fmt.Errorf("wrong number of args: want 2 or 3, got %d", len(args))
	}
	return key, bits, input, nil
}

func deriveKey(key string, bits int) []byte {
	h := sha256.Sum256([]byte(key))
	return h[:bits/8]
}

func pkcs7Pad(b []byte, size int) []byte {
	n := size - len(b)%size
	pad := make([]byte, n)
	for i := range pad {
		pad[i] = byte(n)
	}
	return append(b, pad...)
}

func pkcs7Unpad(b []byte, size int) ([]byte, error) {
	if len(b) == 0 {
		return nil, fmt.Errorf("empty input")
	}
	n := int(b[len(b)-1])
	if n == 0 || n > size || n > len(b) {
		return nil, fmt.Errorf("invalid padding")
	}
	return b[:len(b)-n], nil
}

// RSAGenerateKey generates an RSA private key in PEM format.
func (cryptoFuncs) RSAGenerateKey(args ...interface{}) (string, error) {
	bits := 4096
	if len(args) > 0 {
		b, err := toInt64(args[0])
		if err != nil {
			return "", err
		}
		bits = int(b)
	}
	if len(args) > 1 {
		return "", fmt.Errorf("wrong number of args")
	}
	key, err := rsa.GenerateKey(rand.Reader, bits)
	if err != nil {
		return "", err
	}
	return pemEncodeRSAPrivate(key), nil
}

func pemEncodeRSAPrivate(key *rsa.PrivateKey) string {
	b := x509.MarshalPKCS1PrivateKey(key)
	return string(pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: b}))
}

// RSADerivePublicKey returns the public key for a private key.
func (cryptoFuncs) RSADerivePublicKey(key string) (string, error) {
	priv, err := parseRSAPrivate(key)
	if err != nil {
		return "", err
	}
	b, err := x509.MarshalPKIXPublicKey(&priv.PublicKey)
	if err != nil {
		return "", err
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: b})), nil
}

func parseRSAPrivate(key string) (*rsa.PrivateKey, error) {
	block, _ := pem.Decode([]byte(key))
	if block == nil {
		return nil, fmt.Errorf("could not decode PEM data")
	}
	switch block.Type {
	case "RSA PRIVATE KEY":
		return x509.ParsePKCS1PrivateKey(block.Bytes)
	case "PRIVATE KEY":
		k, err := x509.ParsePKCS8PrivateKey(block.Bytes)
		if err != nil {
			return nil, err
		}
		rk, ok := k.(*rsa.PrivateKey)
		if !ok {
			return nil, fmt.Errorf("not an RSA key")
		}
		return rk, nil
	}
	return nil, fmt.Errorf("unsupported key type %q", block.Type)
}

func parsePublicKey(key string) (interface{}, error) {
	block, _ := pem.Decode([]byte(key))
	if block == nil {
		return nil, fmt.Errorf("could not decode PEM data")
	}
	switch block.Type {
	case "RSA PUBLIC KEY":
		return x509.ParsePKCS1PublicKey(block.Bytes)
	case "PUBLIC KEY":
		return x509.ParsePKIXPublicKey(block.Bytes)
	}
	return nil, fmt.Errorf("unsupported key type %q", block.Type)
}

// RSAEncrypt encrypts the input with the given RSA public key.
func (cryptoFuncs) RSAEncrypt(key string, input string) ([]byte, error) {
	pub, err := parsePublicKey(key)
	if err != nil {
		return nil, err
	}
	pk, ok := pub.(*rsa.PublicKey)
	if !ok {
		return nil, fmt.Errorf("not an RSA public key")
	}
	return rsa.EncryptPKCS1v15(rand.Reader, pk, []byte(input))
}

// RSADecrypt decrypts the input with the given RSA private key.
func (cryptoFuncs) RSADecrypt(key string, input []byte) (string, error) {
	b, err := cryptoFuncs{}.RSADecryptBytes(key, input)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

// RSADecryptBytes decrypts the input with the given RSA private key.
func (cryptoFuncs) RSADecryptBytes(key string, input []byte) ([]byte, error) {
	priv, err := parseRSAPrivate(key)
	if err != nil {
		return nil, err
	}
	return rsa.DecryptPKCS1v15(rand.Reader, priv, input)
}

// ECDSAGenerateKey generates an ECDSA private key in PEM format.
func (cryptoFuncs) ECDSAGenerateKey(args ...interface{}) (string, error) {
	curve := elliptic.P256()
	if len(args) > 0 {
		c, err := asString(args[0])
		if err != nil {
			return "", err
		}
		curve, err = curveByName(c)
		if err != nil {
			return "", err
		}
	}
	key, err := ecdsa.GenerateKey(curve, rand.Reader)
	if err != nil {
		return "", err
	}
	b, err := x509.MarshalECPrivateKey(key)
	if err != nil {
		return "", err
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: b})), nil
}

func curveByName(name string) (elliptic.Curve, error) {
	switch strings.ToLower(name) {
	case "p224", "secp224r1":
		return elliptic.P224(), nil
	case "p256", "secp256r1", "":
		return elliptic.P256(), nil
	case "p384", "secp384r1":
		return elliptic.P384(), nil
	case "p521", "secp521r1":
		return elliptic.P521(), nil
	}
	return nil, fmt.Errorf("unsupported curve: %s", name)
}

// ECDSADerivePublicKey returns the public key for an ECDSA private key.
func (cryptoFuncs) ECDSADerivePublicKey(key string) (string, error) {
	block, _ := pem.Decode([]byte(key))
	if block == nil {
		return "", fmt.Errorf("could not decode PEM data")
	}
	k, err := x509.ParseECPrivateKey(block.Bytes)
	if err != nil {
		return "", err
	}
	b, err := x509.MarshalPKIXPublicKey(&k.PublicKey)
	if err != nil {
		return "", err
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: b})), nil
}

// Ed25519GenerateKey generates an Ed25519 private key in PEM format.
func (cryptoFuncs) Ed25519GenerateKey() (string, error) {
	_, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return "", err
	}
	return pemEncodeEd25519(priv), nil
}

// Ed25519GenerateKeyFromSeed generates an Ed25519 key from a seed.
func (cryptoFuncs) Ed25519GenerateKeyFromSeed(encoding, seed string) (string, error) {
	var b []byte
	var err error
	switch encoding {
	case "base64":
		b, err = base64.StdEncoding.DecodeString(seed)
	case "hex":
		b, err = hex.DecodeString(seed)
	case "seed":
		b = []byte(seed)
	default:
		return "", fmt.Errorf("unsupported encoding: %s", encoding)
	}
	if err != nil {
		return "", err
	}
	if len(b) < ed25519.SeedSize {
		return "", fmt.Errorf("seed must be at least %d bytes", ed25519.SeedSize)
	}
	priv := ed25519.NewKeyFromSeed(b[:ed25519.SeedSize])
	return pemEncodeEd25519(priv), nil
}

func pemEncodeEd25519(priv ed25519.PrivateKey) string {
	b, err := x509.MarshalPKCS8PrivateKey(priv)
	if err != nil {
		return ""
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: b}))
}

// Ed25519DerivePublicKey returns the public key for an Ed25519 private key.
func (cryptoFuncs) Ed25519DerivePublicKey(key string) (string, error) {
	block, _ := pem.Decode([]byte(key))
	if block == nil {
		return "", fmt.Errorf("could not decode PEM data")
	}
	k, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	if err != nil {
		return "", err
	}
	b, err := x509.MarshalPKIXPublicKey(k.(ed25519.PrivateKey).Public())
	if err != nil {
		return "", err
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: b})), nil
}

