func csvArgs(args []interface{}) (string, string, string, error) {
	var delim = ","
	var header = ""
	var input string
	switch len(args) {
	case 1:
		s, err := asString(args[0])
		if err != nil {
			return "", "", "", err
		}
		input = s
	case 2:
		s, ok := args[0].(string)
		if ok {
			// delim, input
			delim = s
			h, err := asString(args[1])
			if err != nil {
				return "", "", "", err
			}
			header, input = "", h
			break
		}
		d, err := asString(args[0])
		if err != nil {
			return "", "", "", err
		}
		delim = d
		s2, err := asString(args[1])
		if err != nil {
