func parseCSVWith(delim, in string) ([][]string, error) {
	r := csv.NewReader(strings.NewReader(in))
	r.Comma = rune(delim[0])
	return r.ReadAll()
}

func parseCSVByRow(delim, header, in string) ([]map[string]interface{}, error) {
	rows, err := parseCSVWith(delim, in)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return []map[string]interface{}{}, nil
	}
	if header == "" {
		header = strings.Join(rows[0], ",")
		rows = rows[1:]
	}
	keys := strings.Split(header, ",")
	out := []map[string]interface{}{}
	for _, row := range rows {
		m := map[string]interface{}{}
		for i, k := range keys {
			if i < len(row) {
				m[k] = row[i]
			}
		}
		out = append(out, m)
	}
	return out, nil
}

func parseCSVByColumn(delim, header, in string) (map[string]interface{}, error) {
	rows, err := parseCSVWith(delim, in)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 {
		return map[string]interface{}{}, nil
	}
	if header == "" {
		header = strings.Join(rows[0], ",")
		rows = rows[1:]
	}
	keys := strings.Split(header, ",")
	out := map[string]interface{}{}
	for i, k := range keys {
		col := []interface{}{}
		for _, row := range rows {
			if i < len(row) {
				col = append(col, row[i])
			}
		}
		out[k] = col
	}
	return out, nil
}

