// ToTOML serializes a value as TOML.
func (dataFuncs) ToTOML(in interface{}) (string, error) {
	var b strings.Builder
	if err := toTOMLValue(&b, reflect.ValueOf(in), 0); err != nil {
		return "", err
	}
	return b.String(), nil
}

func toTOMLValue(b *strings.Builder, v reflect.Value, indent int) error {
	v = indirect(v)
	switch v.Kind() {
	case reflect.Map:
		keys := make([]string, 0, v.Len())
		for _, k := range v.MapKeys() {
			keys = append(keys, toStringValue(k.Interface()))
		}
		sort.Strings(keys)
		for _, k := range keys {
			val := v.MapIndex(reflect.ValueOf(k))
			b.WriteString(strings.Repeat("  ", indent))
			b.WriteString(k)
			b.WriteString(" = ")
			if err := writeTOMLValue(b, val, indent); err != nil {
				return err
			}
			b.WriteString("\n")
		}
		return nil
	}
	return writeTOMLValue(b, v, indent)
}

func writeTOMLValue(b *strings.Builder, v reflect.Value, indent int) error {
	v = indirect(v)
	switch v.Kind() {
	case reflect.String:
		b.WriteString(strconv.Quote(v.String()))
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		b.WriteString(strconv.FormatInt(v.Int(), 10))
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		b.WriteString(strconv.FormatUint(v.Uint(), 10))
	case reflect.Float32, reflect.Float64:
		b.WriteString(strconv.FormatFloat(v.Float(), 'g', -1, 64))
	case reflect.Bool:
		b.WriteString(strconv.FormatBool(v.Bool()))
	case reflect.Slice, reflect.Array:
		b.WriteString("[")
		for i := 0; i < v.Len(); i++ {
			if i > 0 {
				b.WriteString(", ")
			}
			if err := writeTOMLValue(b, v.Index(i), indent); err != nil {
				return err
			}
		}
		b.WriteString("]")
	case reflect.Map:
		b.WriteString("\n")
		return toTOMLValue(b, v, indent+1)
	default:
		return fmt.Errorf("unable to serialize %s as TOML", v.Type())
	}
	return nil
}

