func (dataFuncs) ToCSV(args ...interface{}) (string, error) {
	var delim = ","
	var input interface{}
	switch len(args) {
	case 1:
		input = args[0]
	case 2:
		d, err := asString(args[0])
		if err != nil {
			return "", err
		}
		delim = d
		input = args[1]
	default:
		return "", fmt.Errorf("wrong number of args: want 1 or 2, got %d", len(args))
	}
	list, err := listToSlice(input)
	if err != nil {
		return "", err
	}
	var b strings.Builder
	w := csv.NewWriter(&b)
	w.Comma = rune(delim[0])
	for _, row := range list {
		cols, err := listToSlice(row)
		if err != nil {
			return "", err
		}
		rec := make([]string, 0, len(cols))
		for _, c := range cols {
			rec = append(rec, toStringValue(c))
		}
		if err := w.Write(rec); err != nil {
			return "", err
		}
	}
	w.Flush()
	return b.String(), nil
}

