package funcs

import (
	"fmt"
	"math/big"
	"net"
	"reflect"
	"sort"
	"strconv"
	"strings"
)

// sockAddrVal describes a socket address.
type sockAddrVal struct {
	Address interface{}
	IPAddr  interface{}
	Mask    interface{}
	Port    int
}

// ifAddr describes an interface address.
type ifAddr struct {
	Flags        int
	HardwareAddr interface{}
	Index        int
	MTU          int
	Name         string
	SockAddr     *sockAddrVal
}

// sockaddrFuncs is the sockaddr namespace.
type sockaddrFuncs struct{}

func sockaddrNS() sockaddrFuncs { return sockaddrFuncs{} }

func getAllInterfaces() ([]ifAddr, error) {
	ifaces, err := net.Interfaces()
	if err != nil {
		return nil, err
	}
	out := []ifAddr{}
	for _, ifc := range ifaces {
		addrs, err := ifc.Addrs()
		if err != nil {
			continue
		}
		for _, a := range addrs {
			ipnet, ok := a.(*net.IPNet)
			if !ok {
				continue
			}
			sa := &sockAddrVal{IPAddr: nil, Port: 0}
			if ip4 := ipnet.IP.To4(); ip4 != nil {
				sa.Address = big.NewInt(int64(ip4ToUint(ip4)))
				sa.Mask = big.NewInt(int64(ip4ToUint(net.IPMask(ipnet.Mask))))
			} else {
				sa.Address = new(big.Int).SetBytes(ipnet.IP.To16())
				sa.Mask = new(big.Int).SetBytes(net.IPMask(ipnet.Mask).To16())
			}
			out = append(out, ifAddr{
				Flags:    int(ifc.Flags),
				Index:    ifc.Index,
				MTU:      ifc.MTU,
				Name:     ifc.Name,
				SockAddr: sa,
			})
		}
	}
	return out, nil
}

func ip4ToUint(ip net.IP) uint32 {
	return uint32(ip[0])<<24 | uint32(ip[1])<<16 | uint32(ip[2])<<8 | uint32(ip[3])
}

// GetAllInterfaces returns all interfaces.
func (sockaddrFuncs) GetAllInterfaces() ([]ifAddr, error) { return getAllInterfaces() }

// GetDefaultInterfaces returns the interfaces with a default route.
func (sockaddrFuncs) GetDefaultInterfaces() ([]ifAddr, error) {
	addrs, err := getAllInterfaces()
	if err != nil {
		return nil, err
	}
	return sockaddrFuncs{}.Exclude("rfc1918", "true", addrs)
}

// GetPrivateInterfaces returns the interfaces with RFC1918 addresses.
func (sockaddrFuncs) GetPrivateInterfaces() ([]ifAddr, error) {
	addrs, err := getAllInterfaces()
	if err != nil {
		return nil, err
	}
	return sockaddrFuncs{}.Include("rfc1918", "true", addrs)
}

// GetPublicInterfaces returns the interfaces with public addresses.
func (sockaddrFuncs) GetPublicInterfaces() ([]ifAddr, error) {
	addrs, err := getAllInterfaces()
	if err != nil {
		return nil, err
	}
	return sockaddrFuncs{}.Exclude("rfc1918", "true", addrs)
}

// GetPrivateIP returns the first private IP address.
func (sockaddrFuncs) GetPrivateIP() (string, error) {
	addrs, err := sockaddrFuncs{}.GetPrivateInterfaces()
	if err != nil {
		return "", err
	}
	return sockaddrFuncs{}.Attr("address", addrs)
}

// GetPrivateIPs returns all private IP addresses.
func (sockaddrFuncs) GetPrivateIPs() ([]string, error) {
	addrs, err := sockaddrFuncs{}.GetPrivateInterfaces()
	if err != nil {
		return nil, err
	}
	return sockaddrFuncs{}.Attr("address", addrs).([]string), nil
}

// GetPublicIP returns the first public IP address.
func (sockaddrFuncs) GetPublicIP() (string, error) {
	addrs, err := sockaddrFuncs{}.GetPublicInterfaces()
	if err != nil {
		return "", err
	}
	return sockaddrFuncs{}.Attr("address", addrs)
}

// GetPublicIPs returns all public IP addresses.
func (sockaddrFuncs) GetPublicIPs() ([]string, error) {
	addrs, err := sockaddrFuncs{}.GetPublicInterfaces()
	if err != nil {
		return nil, err
	}
	return sockaddrFuncs{}.Attr("address", addrs).([]string), nil
}

// GetInterfaceIP returns the IP of the named interface.
func (sockaddrFuncs) GetInterfaceIP(name string) (string, error) {
	addrs, err := getAllInterfaces()
	if err != nil {
		return "", err
	}
	filtered, err := sockaddrFuncs{}.Include("name", name, addrs)
	if err != nil {
		return "", err
	}
	return sockaddrFuncs{}.Attr("address", filtered)
}

// GetInterfaceIPs returns the IPs of the named interface.
func (sockaddrFuncs) GetInterfaceIPs(name string) ([]string, error) {
	addrs, err := getAllInterfaces()
	if err != nil {
		return nil, err
	}
	filtered, err := sockaddrFuncs{}.Include("name", name, addrs)
	if err != nil {
		return nil, err
	}
	return sockaddrFuncs{}.Attr("address", filtered).([]string), nil
}

func addrString(a ifAddr) string {
	switch v := a.SockAddr.Address.(type) {
	case *big.Int:
		if v.IsUint64() && v.Uint64() <= 0xffffffff {
			return uintToIP4(uint32(v.Uint64())).String()
		}
		return bigToIP6(v).String()
	}
	return ""
}

func uintToIP4(v uint32) net.IP {
	ip := make(net.IP, 4)
	ip[0] = byte(v >> 24)
	ip[1] = byte(v >> 16)
	ip[2] = byte(v >> 8)
	ip[3] = byte(v)
	return ip
}

func bigToIP6(v *big.Int) net.IP {
	b := make([]byte, 16)
	bs := v.Bytes()
	copy(b[16-len(bs):], bs)
	return net.IP(b)
}

func isRFC1918(a ifAddr) bool {
	s := addrString(a)
	ip := net.ParseIP(s)
	if ip == nil {
		return false
	}
	return ip.IsPrivate()
}

func matchSelector(selector, value string, a ifAddr) bool {
	switch strings.ToLower(selector) {
	case "type":
		s := addrString(a)
		ip := net.ParseIP(s)
		if ip == nil {
			return false
		}
		switch strings.ToLower(value) {
		case "ipv4":
			return ip.To4() != nil
		case "ipv6":
			return ip.To4() == nil
		case "all", "unix":
			return false
		}
		return false
	case "name":
		return a.Name == value
	case "address":
		return addrString(a) == value
	case "port":
		return strconv.Itoa(a.SockAddr.Port) == value
	case "index":
		return strconv.Itoa(a.Index) == value
	case "flags":
		return strconv.Itoa(a.Flags) == value
	case "rfc1918":
		b, err := strconv.ParseBool(value)
		if err != nil {
			return false
		}
		return b == isRFC1918(a)
	case "rfc4193", "rfc6598":
		return false
	}
	return false
}

// Include filters the interfaces matching the selector.
func (sockaddrFuncs) Include(selector, value string, addrs []ifAddr) ([]ifAddr, error) {
	out := []ifAddr{}
	for _, a := range addrs {
		if matchSelector(selector, value, a) {
			out = append(out, a)
		}
	}
	return out, nil
}

// Exclude filters out the interfaces matching the selector.
func (sockaddrFuncs) Exclude(selector, value string, addrs []ifAddr) ([]ifAddr, error) {
	out := []ifAddr{}
	for _, a := range addrs {
		if !matchSelector(selector, value, a) {
			out = append(out, a)
		}
	}
	return out, nil
}

// Sort sorts the interfaces by the given selector.
func (sockaddrFuncs) Sort(selector string, addrs []ifAddr) ([]ifAddr, error) {
	keys := strings.Split(selector, ",")
	out := make([]ifAddr, len(addrs))
	copy(out, addrs)
	sort.SliceStable(out, func(i, j int) bool {
		for _, k := range keys {
			desc := false
			k = strings.TrimSpace(k)
			if strings.HasPrefix(k, "-") {
				desc = true
				k = strings.TrimPrefix(k, "-")
			}
			a, b := attrValue(k, out[i]), attrValue(k, out[j])
			if a == b {
				continue
			}
			if desc {
				return a > b
			}
			return a < b
		}
		return false
	})
	return out, nil
}

func attrValue(selector string, a ifAddr) string {
	switch strings.ToLower(selector) {
	case "name":
		return a.Name
	case "address":
		return addrString(a)
	case "port":
		return strconv.Itoa(a.SockAddr.Port)
	case "index":
		return strconv.Itoa(a.Index)
	case "flags":
		return strconv.Itoa(a.Flags)
	case "type":
		s := addrString(a)
		ip := net.ParseIP(s)
		if ip == nil {
			return ""
		}
		if ip.To4() != nil {
			return "ipv4"
		}
		return "ipv6"
	}
	return ""
}

// Attr returns the given attribute of the interfaces.
func (sockaddrFuncs) Attr(selector string, addrs []ifAddr) (interface{}, error) {
	if len(addrs) == 0 {
		return reflect.ValueOf(""), nil
	}
	if len(addrs) == 1 {
		return reflect.ValueOf(attrValue(selector, addrs[0])), nil
	}
	out := make([]string, 0, len(addrs))
	for _, a := range addrs {
		out = append(out, attrValue(selector, a))
	}
	return reflect.ValueOf(out), nil
}

// Join joins the given attribute of the interfaces.
func (sockaddrFuncs) Join(selector, sep string, addrs []ifAddr) (string, error) {
	out := []string{}
	for _, a := range addrs {
		out = append(out, attrValue(selector, a))
	}
	return strings.Join(out, sep), nil
}

// Limit returns at most n interfaces.
func (sockaddrFuncs) Limit(n interface{}, addrs []ifAddr) ([]ifAddr, error) {
	c, err := toInt64(n)
	if err != nil {
		return nil, err
	}
	if int(c) > len(addrs) {
		return addrs, nil
	}
	return addrs[:c], nil
}

// Offset skips the first n interfaces.
func (sockaddrFuncs) Offset(n interface{}, addrs []ifAddr) ([]ifAddr, error) {
	c, err := toInt64(n)
	if err != nil {
		return nil, err
	}
	if int(c) > len(addrs) {
		return []ifAddr{}, nil
	}
	return addrs[c:], nil
}

// Unique returns the interfaces with unique addresses.
func (sockaddrFuncs) Unique(addrs []ifAddr) ([]ifAddr, error) {
	out := []ifAddr{}
	seen := map[string]bool{}
	for _, a := range addrs {
		if seen[addrString(a)] {
			continue
		}
		seen[addrString(a)] = true
		out = append(out, a)
	}
	return out, nil
}

// Math returns the sum of the selected attribute.
func (sockaddrFuncs) Math(selector string, addrs []ifAddr) (string, error) {
	total := big.NewInt(0)
	for _, a := range addrs {
		switch v := a.SockAddr.Address.(type) {
		case *big.Int:
			total.Add(total, v)
		}
	}
	return total.String(), nil
}

