			k = strings.TrimSpace(k)
			if strings.HasPrefix(k, "-") {
				desc = true
				k = strings.TrimPrefix(k, "-")
			}
			a, b := attrValue(k, out[i]), attrValue(k, out[j])
			if a == b {
				continue
			}
			if desc {
				return a > b
			}
			return a < b
		}
		return false
	})
	return out, nil
}

