package funcs

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// jqFuncs is the coll.JQ implementation.
type jqFuncs struct{}

// JQ runs a jq expression against the input.
func JQ(expr string, in interface{}) (interface{}, error) {
	p, err := parseJQ(expr)
	if err != nil {
		return nil, fmt.Errorf("jq execution: %w", err)
	}
	v, err := p.eval(in, jqEnv{})
	if err != nil {
		return nil, fmt.Errorf("jq execution: %w", err)
	}
	if len(v) == 0 {
		return nil, nil
	}
	return v[0], nil
}

// jqEnv holds variable bindings.
type jqEnv map[string]interface{}

type jqNode interface {
	eval(in interface{}, env jqEnv) ([]interface{}, error)
}

type jqParser struct {
	s   string
	pos int
}

func parseJQ(s string) (jqNode, error) {
	p := &jqParser{s: s}
	n, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	return n, nil
}

func (p *jqParser) skip() {
	for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\t' || p.s[p.pos] == '\n') {
		p.pos++
	}
}

func (p *jqParser) peek() byte {
	if p.pos >= len(p.s) {
		return 0
	}
	return p.s[p.pos]
}

func (p *jqParser) parsePipe() (jqNode, error) {
	left, err := p.parseAlt()
	if err != nil {
		return nil, err
	}
	p.skip()
	if p.peek() == '|' {
		p.pos++
		right, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		return &jqPipe{left: left, right: right}, nil
	}
	return left, nil
}

func (p *jqParser) parseAlt() (jqNode, error) {
	left, err := p.parseComma()
	if err != nil {
		return nil, err
	}
	p.skip()
	if strings.HasPrefix(p.s[p.pos:], "//") {
		p.pos += 2
		right, err := p.parseAlt()
		if err != nil {
			return nil, err
		}
		return &jqAlt{left: left, right: right}, nil
	}
	return left, nil
}

func (p *jqParser) parseComma() (jqNode, error) {
	left, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	items := []jqNode{left}
	for {
		p.skip()
		if p.peek() == ',' {
			p.pos++
			n, err := p.parseAdd()
			if err != nil {
				return nil, err
			}
			items = append(items, n)
			continue
		}
		break
	}
	if len(items) == 1 {
		return left, nil
	}
	return &jqComma{items: items}, nil
}

func (p *jqParser) parseAdd() (jqNode, error) {
	left, err := p.parseMul()
	if err != nil {
		return nil, err
	}
	for {
		p.skip()
		c := p.peek()
		if c != '+' && c != '-' {
			break
		}
		p.pos++
		right, err := p.parseMul()
		if err != nil {
			return nil, err
		}
		left = &jqArith{op: string(c), left: left, right: right}
	}
	return left, nil
}

func (p *jqParser) parseMul() (jqNode, error) {
	left, err := p.parseCmp()
	if err != nil {
		return nil, err
	}
	for {
		p.skip()
		c := p.peek()
		if c != '*' && c != '/' && c != '%' {
			break
		}
		p.pos++
		right, err := p.parseCmp()
		if err != nil {
			return nil, err
		}
		left = &jqArith{op: string(c), left: left, right: right}
	}
	return left, nil
}

func (p *jqParser) parseCmp() (jqNode, error) {
	left, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	p.skip()
	for _, op := range []string{"==", "!=", "<=", ">=", "<", ">"} {
		if strings.HasPrefix(p.s[p.pos:], op) {
			p.pos += len(op)
			right, err := p.parsePostfix()
			if err != nil {
				return nil, err
			}
			return &jqCmp{op: op, left: left, right: right}, nil
		}
	}
	return left, nil
}

func (p *jqParser) parsePostfix() (jqNode, error) {
	n, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for {
		p.skip()
		switch p.peek() {
		case '.':
			// .foo or .["foo"]
			if p.pos+1 < len(p.s) && p.s[p.pos+1] == '[' {
				p.pos++
				continue
			}
			p.pos++
			name := p.parseIdent()
			if name == "" {
				return n, nil
			}
			n = &jqField{of: n, name: name}
		case '[':
			p.pos++
			p.skip()
			if p.peek() == ']' {
				p.pos++
				n = &jqIterate{of: n}
				continue
			}
			idx, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			p.skip()
			if p.peek() != ']' {
				return nil, fmt.Errorf("expected ]")
			}
			p.pos++
			n = &jqIndex{of: n, idx: idx}
		case '?':
			p.pos++
		default:
			return n, nil
		}
	}
}

func (p *jqParser) parseIdent() string {
	start := p.pos
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
			p.pos++
			continue
		}
		break
	}
	return p.s[start:p.pos]
}

func (p *jqParser) parsePrimary() (jqNode, error) {
	p.skip()
	switch p.peek() {
	case '.':
		p.pos++
		// .foo
		name := p.parseIdent()
		if name != "" {
			return &jqField{of: &jqIdentity{}, name: name}, nil
		}
		return &jqIdentity{}, nil
	case '$':
		p.pos++
		name := p.parseIdent()
		return &jqVar{name: name}, nil
	case '[':
		p.pos++
		p.skip()
		if p.peek() == ']' {
			p.pos++
			return &jqArray{items: nil}, nil
		}
		items := []jqNode{}
		for {
			n, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			items = append(items, n)
			p.skip()
			if p.peek() == ',' {
				p.pos++
				continue
			}
			break
		}
		if p.peek() != ']' {
			return nil, fmt.Errorf("expected ]")
		}
		p.pos++
		return &jqArray{items: items}, nil
	case '{':
		p.pos++
		pairs := []jqPair{}
		for {
			p.skip()
			if p.peek() == '}' {
				p.pos++
				break
			}
			k := p.parseIdent()
			if k == "" {
				return nil, fmt.Errorf("expected object key")
			}
			p.skip()
			if p.peek() == ':' {
				p.pos++
				v, err := p.parseAlt()
				if err != nil {
					return nil, err
				}
				pairs = append(pairs, jqPair{key: &jqLiteral{v: k}, val: v})
			} else {
				pairs = append(pairs, jqPair{key: &jqLiteral{v: k}, val: &jqField{of: &jqIdentity{}, name: k}})
			}
			p.skip()
			if p.peek() == ',' {
				p.pos++
				continue
			}
			if p.peek() != '}' {
				return nil, fmt.Errorf("expected }")
			}
			p.pos++
			break
		}
		return &jqObject{pairs: pairs}, nil
	case '"':
		s, err := p.parseString()
		if err != nil {
			return nil, err
		}
		return &jqLiteral{v: s}, nil
	default:
		if (p.peek() >= '0' && p.peek() <= '9') || p.peek() == '-' {
			start := p.pos
			if p.peek() == '-' {
				p.pos++
			}
			for p.pos < len(p.s) && (p.s[p.pos] >= '0' && p.s[p.pos] <= '9' || p.s[p.pos] == '.') {
				p.pos++
			}
			v, err := strconv.ParseFloat(p.s[start:p.pos], 64)
			if err != nil {
				return nil, err
			}
			return &jqLiteral{v: v}, nil
		}
		name := p.parseIdent()
		if name == "" {
			return nil, fmt.Errorf("unexpected character %q", string(p.peek()))
		}
		switch name {
		case "true":
			return &jqLiteral{v: true}, nil
		case "false":
			return &jqLiteral{v: false}, nil
		case "null":
			return &jqLiteral{v: nil}, nil
		}
		if p.peek() == '(' {
			p.pos++
			args := []jqNode{}
			for {
				n, err := p.parsePipe()
				if err != nil {
					return nil, err
				}
				args = append(args, n)
				p.skip()
				if p.peek() == ';' {
					p.pos++
					continue
				}
				break
			}
			if p.peek() != ')' {
				return nil, fmt.Errorf("expected )")
			}
			p.pos++
			return &jqFuncCall{name: name, args: args}, nil
		}
		return &jqFuncCall{name: name}, nil
	}
}

func (p *jqParser) parseString() (string, error) {
	if p.peek() != '"' {
		return "", fmt.Errorf("expected string")
	}
	p.pos++
	var b strings.Builder
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == '"' {
			p.pos++
			return b.String(), nil
		}
		if c == '\\' && p.pos+1 < len(p.s) {
			p.pos++
			switch p.s[p.pos] {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			default:
				b.WriteByte(p.s[p.pos])
			}
			p.pos++
			continue
		}
		b.WriteByte(c)
		p.pos++
	}
	return "", fmt.Errorf("unterminated string")
}

type jqIdentity struct{}

func (jqIdentity) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	return []interface{}{in}, nil
}

type jqPipe struct {
	left, right jqNode
}

func (n *jqPipe) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	lefts, err := n.left.eval(in, env)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, l := range lefts {
		r, err := n.right.eval(l, env)
		if err != nil {
			return nil, err
		}
		out = append(out, r...)
	}
	return out, nil
}

type jqComma struct {
	items []jqNode
}

func (n *jqComma) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	out := []interface{}{}
	for _, i := range n.items {
		v, err := i.eval(in, env)
		if err != nil {
			return nil, err
		}
		out = append(out, v...)
	}
	return out, nil
}

type jqAlt struct {
	left, right jqNode
}

func (n *jqAlt) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	lefts, err := n.left.eval(in, env)
	if err != nil {
		return nil, err
	}
	var out []interface{}
	for _, l := range lefts {
		if !isTruthy(l) {
			continue
		}
		out = append(out, l)
	}
	if len(out) > 0 {
		return out, nil
	}
	return n.right.eval(in, env)
}

type jqField struct {
	of   jqNode
	name string
}

func (n *jqField) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	parents, err := n.of.eval(in, env)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, p := range parents {
		v, err := jqIndexValue(p, n.name)
		if err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	return out, nil
}

func jqIndexValue(in interface{}, key string) (interface{}, error) {
	switch t := in.(type) {
	case map[string]interface{}:
		return t[key], nil
	case nil:
		return nil, nil
	}
	return nil, fmt.Errorf("expected an object but got: %s (%s)", jqTypeName(in), jqStringify(in))
}

func jqTypeName(in interface{}) string {
	switch in.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case float64, float32, int, int64:
		return "number"
	case string:
		return "string"
	case []interface{}:
		return "array"
	case map[string]interface{}:
		return "object"
	}
	return "unknown"
}

func jqStringify(in interface{}) string {
	b, err := marshalJSONCompact(in)
	if err != nil {
		return "?"
	}
	return b
}

type jqIndex struct {
	of  jqNode
	idx jqNode
}

func (n *jqIndex) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	parents, err := n.of.eval(in, env)
	if err != nil {
		return nil, err
	}
	idxs, err := n.idx.eval(in, env)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, p := range parents {
		for _, idx := range idxs {
			v, err := jqIndexValue(p, jqToString(idx))
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
	}
	return out, nil
}

func jqToString(v interface{}) string {
	switch t := v.(type) {
	case string:
		return t
	case float64:
		return strconv.FormatFloat(t, 'g', -1, 64)
	}
	return fmt.Sprintf("%v", v)
}

type jqIterate struct {
	of jqNode
}

func (n *jqIterate) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	parents, err := n.of.eval(in, env)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, p := range parents {
		switch t := p.(type) {
		case []interface{}:
			out = append(out, t...)
		case map[string]interface{}:
			for _, v := range t {
				out = append(out, v)
			}
		default:
			return nil, fmt.Errorf("cannot iterate over: %s (%s)", jqTypeName(p), jqStringify(p))
		}
	}
	return out, nil
}

type jqVar struct {
	name string
}

func (n *jqVar) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	v, ok := env[n.name]
	if !ok {
		return nil, fmt.Errorf("$%s is not defined", n.name)
	}
	return []interface{}{v}, nil
}

type jqLiteral struct {
	v interface{}
}

func (n *jqLiteral) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	return []interface{}{n.v}, nil
}

type jqArray struct {
	items []jqNode
}

func (n *jqArray) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	out := []interface{}{}
	for _, i := range n.items {
		v, err := i.eval(in, env)
		if err != nil {
			return nil, err
		}
		out = append(out, v...)
	}
	return []interface{}{out}, nil
}

type jqPair struct {
	key jqNode
	val jqNode
}

type jqObject struct {
	pairs []jqPair
}

func (n *jqObject) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	m := map[string]interface{}{}
	for _, p := range n.pairs {
		vals, err := p.val.eval(in, env)
		if err != nil {
			return nil, err
		}
		if len(vals) == 0 {
			continue
		}
		m[jqToString(p.key)] = vals[0]
	}
	return []interface{}{m}, nil
}

type jqArith struct {
	op          string
	left, right jqNode
}

func (n *jqArith) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	lefts, err := n.left.eval(in, env)
	if err != nil {
		return nil, err
	}
	rights, err := n.right.eval(in, env)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, l := range lefts {
		for _, r := range rights {
			v, err := jqArithValue(n.op, l, r)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
	}
	return out, nil
}

func jqArithValue(op string, l, r interface{}) (interface{}, error) {
	switch op {
	case "+":
		switch lt := l.(type) {
		case string:
			if rs, ok := r.(string); ok {
				return lt + rs, nil
			}
		case []interface{}:
			if rs, ok := r.([]interface{}); ok {
				return append(append([]interface{}{}, lt...), rs...), nil
			}
		case map[string]interface{}:
			if rm, ok := r.(map[string]interface{}); ok {
				m := map[string]interface{}{}
				for k, v := range lt {
					m[k] = v
				}
				for k, v := range rm {
					m[k] = v
				}
				return m, nil
			}
		}
		lf, lok := toFloat(l)
		rf, rok := toFloat(r)
		if lok != nil || rok != nil {
			return nil, fmt.Errorf("cannot add: %s (%s) and %s (%s)", jqTypeName(l), jqStringify(l), jqTypeName(r), jqStringify(r))
		}
		return lf + rf, nil
	case "-":
		lf, err := toFloat(l)
		if err != nil {
			return nil, fmt.Errorf("cannot subtract: %s (%s) and %s (%s)", jqTypeName(l), jqStringify(l), jqTypeName(r), jqStringify(r))
		}
		rf, err := toFloat(r)
		if err != nil {
			return nil, fmt.Errorf("cannot subtract: %s (%s) and %s (%s)", jqTypeName(l), jqStringify(l), jqTypeName(r), jqStringify(r))
		}
		return lf - rf, nil
	case "*":
		lf, err := toFloat(l)
		if err != nil {
			return nil, fmt.Errorf("cannot multiply: %s (%s) and %s (%s)", jqTypeName(l), jqStringify(l), jqTypeName(r), jqStringify(r))
		}
		rf, err := toFloat(r)
		if err != nil {
			return nil, fmt.Errorf("cannot multiply: %s (%s) and %s (%s)", jqTypeName(l), jqStringify(l), jqTypeName(r), jqStringify(r))
		}
		return lf * rf, nil
	case "/":
		lf, err := toFloat(l)
		if err != nil {
			return nil, fmt.Errorf("cannot divide: %s (%s) and %s (%s)", jqTypeName(l), jqStringify(l), jqTypeName(r), jqStringify(r))
		}
		rf, err := toFloat(r)
		if err != nil {
			return nil, fmt.Errorf("cannot divide: %s (%s) and %s (%s)", jqTypeName(l), jqStringify(l), jqTypeName(r), jqStringify(r))
		}
		if rf == 0 {
			return nil, fmt.Errorf("cannot divide by zero")
		}
		return lf / rf, nil
	case "%":
		li, err := toInt64(l)
		if err != nil {
			return nil, fmt.Errorf("cannot modulo: %s (%s) and %s (%s)", jqTypeName(l), jqStringify(l), jqTypeName(r), jqStringify(r))
		}
		ri, err := toInt64(r)
		if err != nil {
			return nil, fmt.Errorf("cannot modulo: %s (%s) and %s (%s)", jqTypeName(l), jqStringify(l), jqTypeName(r), jqStringify(r))
		}
		if ri == 0 {
			return nil, fmt.Errorf("cannot modulo by zero")
		}
		return li % ri, nil
	}
	return nil, fmt.Errorf("unknown operator %q", op)
}

func toFloat(v interface{}) (float64, error) {
	switch t := v.(type) {
	case float64:
		return t, nil
	case int:
		return float64(t), nil
	case int64:
		return float64(t), nil
	}
	return 0, fmt.Errorf("not a number")
}

type jqCmp struct {
	op          string
	left, right jqNode
}

func (n *jqCmp) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	lefts, err := n.left.eval(in, env)
	if err != nil {
		return nil, err
	}
	rights, err := n.right.eval(in, env)
	if err != nil {
		return nil, err
	}
	out := []interface{}{}
	for _, l := range lefts {
		for _, r := range rights {
			out = append(out, jqCompare(n.op, l, r))
		}
	}
	return out, nil
}

func jqCompare(op string, l, r interface{}) bool {
	lf, lok := toFloat(l)
	rf, rok := toFloat(r)
	if lok == nil && rok == nil {
		switch op {
		case "==":
			return lf == rf
		case "!=":
			return lf != rf
		case "<":
			return lf < rf
		case "<=":
			return lf <= rf
		case ">":
			return lf > rf
		case ">=":
			return lf >= rf
		}
	}
	ls, rs := jqStringify(l), jqStringify(r)
	switch op {
	case "==":
		return ls == rs
	case "!=":
		return ls != rs
	case "<":
		return ls < rs
	case "<=":
		return ls <= rs
	case ">":
		return ls > rs
	case ">=":
		return ls >= rs
	}
	return false
}

func isTruthy(v interface{}) bool {
	switch t := v.(type) {
	case nil:
		return false
	case bool:
		return t
	case string:
		return t != ""
	case []interface{}:
		return len(t) > 0
	case map[string]interface{}:
		return len(t) > 0
	}
	return true
}

type jqFuncCall struct {
	name string
	args []jqNode
}

func (n *jqFuncCall) eval(in interface{}, env jqEnv) ([]interface{}, error) {
	switch n.name {
	case "empty":
		return nil, nil
	case "length":
		switch t := in.(type) {
		case string:
			return []interface{}{float64(len([]rune(t)))}, nil
		case []interface{}:
			return []interface{}{float64(len(t))}, nil
		case map[string]interface{}:
			return []interface{}{float64(len(t))}, nil
		case nil:
			return []interface{}{float64(0)}, nil
		}
		return nil, fmt.Errorf("has no length")
	case "keys":
		switch t := in.(type) {
		case map[string]interface{}:
			keys := []interface{}{}
			ks := []string{}
			for k := range t {
				ks = append(ks, k)
			}
			sort.Strings(ks)
			for _, k := range ks {
				keys = append(keys, k)
			}
			return []interface{}{keys}, nil
		}
		return nil, fmt.Errorf("%s has no keys", jqTypeName(in))
	case "tostring":
		return []interface{}{jqStringify(in)}, nil
	case "type":
		return []interface{}{jqTypeName(in)}, nil
	case "not":
		return []interface{}{!isTruthy(in)}, nil
	case "map":
		if len(n.args) != 1 {
			return nil, fmt.Errorf("map requires 1 argument")
		}
		list, ok := in.([]interface{})
		if !ok {
			return nil, fmt.Errorf("cannot map over: %s (%s)", jqTypeName(in), jqStringify(in))
		}
		out := []interface{}{}
		for _, v := range list {
			r, err := n.args[0].eval(v, env)
			if err != nil {
				return nil, err
			}
			out = append(out, r...)
		}
		return []interface{}{out}, nil
	case "select":
		if len(n.args) != 1 {
			return nil, fmt.Errorf("select requires 1 argument")
		}
		r, err := n.args[0].eval(in, env)
		if err != nil {
			return nil, err
		}
		out := []interface{}{}
		for _, v := range r {
			if isTruthy(v) {
				out = append(out, in)
			}
		}
		return out, nil
	case "add":
		list, ok := in.([]interface{})
		if !ok {
			return nil, fmt.Errorf("cannot add: %s (%s)", jqTypeName(in), jqStringify(in))
		}
		var total interface{}
		for _, v := range list {
			if total == nil {
				total = v
				continue
			}
			nv, err := jqArithValue("+", total, v)
			if err != nil {
				return nil, err
			}
			total = nv
		}
		return []interface{}{total}, nil
	case "has":
		if len(n.args) != 1 {
			return nil, fmt.Errorf("has requires 1 argument")
		}
		r, err := n.args[0].eval(in, env)
		if err != nil {
			return nil, err
		}
		if len(r) == 0 {
			return nil, nil
		}
		switch t := in.(type) {
		case map[string]interface{}:
			_, ok := t[jqToString(r[0])]
			return []interface{}{ok}, nil
		case []interface{}:
			i, err := toInt64(r[0])
			if err != nil {
				return nil, err
			}
			return []interface{}{int(i) < len(t)}, nil
		}
		return nil, fmt.Errorf("cannot check has: %s (%s)", jqTypeName(in), jqStringify(in))
	}
	return nil, fmt.Errorf("%s is not defined", n.name)
}

