type jsonPathStep struct {
	kind  string // "field", "index", "wild", "desc", "filter"
	name  string
	idx   int
	expr  string
	cmp   string
	value string
}

type jsonPath struct {
	steps []jsonPathStep
}

func parseJSONPath(expr string) (*jsonPath, error) {
	p := &jsonPath{}
	s := strings.TrimPrefix(expr, "$")
	s = strings.TrimPrefix(s, "@")
	i := 0
	descend := false
	for i < len(s) {
		switch s[i] {
		case '.':
			i++
			if i < len(s) && s[i] == '.' {
				i++
				descend = true
			} else {
				descend = false
			}
			// field name
			start := i
			for i < len(s) && (s[i] == '_' || s[i] == '-' || (s[i] >= 'a' && s[i] <= 'z') ||
				(s[i] >= 'A' && s[i] <= 'Z') || (s[i] >= '0' && s[i] <= '9')) {
				i++
			}
			if start == i {
				if i < len(s) && s[i] == '*' {
					i++
					p.steps = append(p.steps, jsonPathStep{kind: "wild", name: "*"})
					continue
				}
				continue
			}
			name := s[start:i]
			if descend {
				p.steps = append(p.steps, jsonPathStep{kind: "desc", name: name})
			} else {
				p.steps = append(p.steps, jsonPathStep{kind: "field", name: name})
			}
		case '[':
			i++
			end := strings.IndexByte(s[i:], ']')
			if end < 0 {
				return nil, fmt.Errorf("unterminated [ in JSONPath expression")
			}
			inner := s[i : i+end]
			i += end + 1
			if strings.HasPrefix(inner, "?(") && strings.HasSuffix(inner, ")") {
				p.steps = append(p.steps, jsonPathStep{kind: "filter", expr: strings.TrimSuffix(strings.TrimPrefix(inner, "?("), ")")})
				continue
			}
			if inner == "*" {
				p.steps = append(p.steps, jsonPathStep{kind: "wild", name: "*"})
				continue
			}
			if strings.HasPrefix(inner, ":") || strings.HasSuffix(inner, ":") || strings.Contains(inner, ":") {
				continue
			}
			n, err := strconv.Atoi(strings.TrimSpace(inner))
			if err != nil {
				name := strings.Trim(inner, "'\"")
				p.steps = append(p.steps, jsonPathStep{kind: "field", name: name})
				continue
			}
			p.steps = append(p.steps, jsonPathStep{kind: "index", idx: n})
		default:
			i++
		}
	}
	return p, nil
}

func (p *jsonPath) eval(in interface{}) ([]interface{}, error) {
	out := []interface{}{in}
	for _, st := range p.steps {
		var next []interface{}
		for _, v := range out {
			switch st.kind {
			case "field":
				if m, ok := v.(map[string]interface{}); ok {
					if cv, ok := m[st.name]; ok {
						next = append(next, cv)
					}
				}
			case "index":
				if l, ok := v.([]interface{}); ok {
					if st.idx >= 0 && st.idx < len(l) {
						next = append(next, l[st.idx])
					}
				}
			case "wild":
				switch t := v.(type) {
				case []interface{}:
					next = append(next, t...)
				case map[string]interface{}:
					keys := make([]string, 0, len(t))
					for k := range t {
						keys = append(keys, k)
					}
					sort.Strings(keys)
					for _, k := range keys {
						next = append(next, t[k])
					}
				}
			case "desc":
				next = append(next, descendField(v, st.name)...)
			case "filter":
				next = append(next, filterValues(v, st.expr)...)
			}
		}
		out = next
	}
	return out, nil
}

func descendField(v interface{}, name string) []interface{} {
	out := []interface{}{}
	switch t := v.(type) {
	case map[string]interface{}:
		if cv, ok := t[name]; ok {
			out = append(out, cv)
		}
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			out = append(out, descendField(t[k], name)...)
		}
	case []interface{}:
		for _, c := range t {
			out = append(out, descendField(c, name)...)
		}
	}
	return out
}

func filterValues(v interface{}, expr string) []interface{} {
	out := []interface{}{}
	list, ok := v.([]interface{})
	if !ok {
		return out
	}
	for _, item := range list {
		m, ok := item.(map[string]interface{})
		if !ok {
			continue
		}
		if evalFilter(expr, m) {
			out = append(out, item)
		}
	}
	return out
}

func evalFilter(expr string, m map[string]interface{}) bool {
	for _, op := range []string{">=", "<=", "==", "!=", ">", "<"} {
		if i := strings.Index(expr, op); i >= 0 {
			left := strings.TrimSpace(expr[:i])
			right := strings.TrimSpace(expr[i+len(op):])
			left = strings.TrimPrefix(left, "@.")
			right = strings.Trim(strings.TrimPrefix(strings.TrimPrefix(right, "@"), "."), "'\"")
			lv, ok := m[left]
			if !ok {
				return false
			}
			lf, lok := toFloat(lv)
			rf, rok := toFloat(right)
			if lok == nil && rok == nil {
				switch op {
				case ">":
					return lf > rf
				case ">=":
					return lf >= rf
				case "<":
					return lf < rf
				case "<=":
					return lf <= rf
				case "==":
					return lf == rf
				case "!=":
					return lf != rf
				}
			}
			ls := toStringValue(lv)
			switch op {
			case "==":
				return ls == right
			case "!=":
				return ls != right
			}
			return false
		}
	}
	return true
}

