package funcs

import (
	"fmt"
	"strconv"
	"strings"
)

// parseCUE parses a limited subset of CUE into a Go value.
func parseCUE(in string) (interface{}, error) {
	p := &cueParser{s: in}
	v, err := p.parseValue()
	if err != nil {
		return nil, fmt.Errorf("unable to process CUE: %w", err)
	}
	p.skip()
	if p.pos < len(p.s) {
		return nil, fmt.Errorf("unable to process CUE: unexpected trailing content")
	}
	return v, nil
}

// toCUE serializes a value as CUE.
func toCUE(in interface{}) (string, error) {
	var b strings.Builder
	if err := writeCUE(&b, in, 0); err != nil {
		return "", err
	}
	return b.String(), nil
}

func writeCUE(b *strings.Builder, in interface{}, indent int) error {
	switch t := in.(type) {
	case nil:
		b.WriteString("null")
	case bool:
		b.WriteString(fmt.Sprintf("%v", t))
	case string:
		b.WriteString(strconv.Quote(t))
	case int, int64, float64:
		b.WriteString(fmt.Sprintf("%v", t))
	case []interface{}:
		b.WriteString("[")
		for i, v := range t {
			if i > 0 {
				b.WriteString(", ")
			}
			if err := writeCUE(b, v, indent); err != nil {
				return err
			}
		}
		b.WriteString("]")
	case map[string]interface{}:
		b.WriteString("{\n")
		keys := sortedKeys(t)
		for _, k := range keys {
			b.WriteString(strings.Repeat("\t", indent+1))
			b.WriteString(k)
			b.WriteString(": ")
			if err := writeCUE(b, t[k], indent+1); err != nil {
				return err
			}
			b.WriteString("\n")
		}
		b.WriteString(strings.Repeat("\t", indent))
		b.WriteString("}")
	default:
		return fmt.Errorf("unable to serialize %T as CUE", in)
	}
	return nil
}

func sortedKeys(m map[string]interface{}) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sortStrings(keys)
	return keys
}

type cueParser struct {
	s   string
	pos int
}

func (p *cueParser) skip() {
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
			continue
		}
		if c == '/' && p.pos+1 < len(p.s) && p.s[p.pos+1] == '/' {
			for p.pos < len(p.s) && p.s[p.pos] != '\n' {
				p.pos++
			}
			continue
		}
		break
	}
}

func (p *cueParser) parseValue() (interface{}, error) {
	p.skip()
	if p.pos >= len(p.s) {
		return nil, fmt.Errorf("reference \"\" not found")
	}
	switch p.s[p.pos] {
	case '{':
		return p.parseObject()
	case '[':
		return p.parseArray()
	case '"':
		return p.parseString()
	}
	// identifier or number
	start := p.pos
	for p.pos < len(p.s) && (p.s[p.pos] == '_' || p.s[p.pos] == '-' || p.s[p.pos] == '.' ||
		(p.s[p.pos] >= 'a' && p.s[p.pos] <= 'z') || (p.s[p.pos] >= 'A' && p.s[p.pos] <= 'Z') ||
		(p.s[p.pos] >= '0' && p.s[p.pos] <= '9')) {
		p.pos++
	}
	name := p.s[start:p.pos]
	if name == "" {
		return nil, fmt.Errorf("unexpected character %q", string(p.s[p.pos]))
	}
	p.skip()
	if p.pos < len(p.s) && p.s[p.pos] == ':' {
		// this is a field; handled by parseObject
		return nil, fmt.Errorf("unexpected ':'")
	}
	switch name {
	case "true":
		return true, nil
	case "false":
		return false, nil
	case "null":
		return nil, nil
	}
	if f, err := strconv.ParseFloat(name, 64); err == nil {
		return f, nil
	}
	return nil, fmt.Errorf("reference %q not found", name)
}

func (p *cueParser) parseObject() (interface{}, error) {
	p.skip()
	if p.s[p.pos] != '{' {
		return nil, fmt.Errorf("expected {")
	}
	p.pos++
	out := map[string]interface{}{}
	for {
		p.skip()
		if p.pos >= len(p.s) {
			return nil, fmt.Errorf("unexpected end of input")
		}
		if p.s[p.pos] == '}' {
			p.pos++
			return out, nil
		}
		key, err := p.parseKey()
		if err != nil {
			return nil, err
		}
		p.skip()
		if p.pos >= len(p.s) || p.s[p.pos] != ':' {
			return nil, fmt.Errorf("expected ':'")
		}
		p.pos++
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		out[key] = v
		p.skip()
		if p.pos < len(p.s) && p.s[p.pos] == ',' {
			p.pos++
			continue
		}
	}
}

func (p *cueParser) parseKey() (string, error) {
	p.skip()
	if p.s[p.pos] == '"' {
		return p.parseString()
	}
	start := p.pos
	for p.pos < len(p.s) && (p.s[p.pos] == '_' || (p.s[p.pos] >= 'a' && p.s[p.pos] <= 'z') ||
		(p.s[p.pos] >= 'A' && p.s[p.pos] <= 'Z') || (p.s[p.pos] >= '0' && p.s[p.pos] <= '9')) {
		p.pos++
	}
	if start == p.pos {
		return "", fmt.Errorf("expected key")
	}
	return p.s[start:p.pos], nil
}

func (p *cueParser) parseArray() (interface{}, error) {
	p.pos++
	out := []interface{}{}
	for {
		p.skip()
		if p.pos >= len(p.s) {
			return nil, fmt.Errorf("unexpected end of input")
		}
		if p.s[p.pos] == ']' {
			p.pos++
			return out, nil
		}
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		out = append(out, v)
		p.skip()
		if p.pos < len(p.s) && p.s[p.pos] == ',' {
			p.pos++
			continue
		}
	}
}

func (p *cueParser) parseString() (string, error) {
	if p.s[p.pos] != '"' {
		return "", fmt.Errorf("expected string")
	}
	p.pos++
	var b strings.Builder
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == '"' {
			p.pos++
			return b.String(), nil
		}
		if c == '\\' && p.pos+1 < len(p.s) {
			p.pos++
			switch p.s[p.pos] {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			default:
				b.WriteByte(p.s[p.pos])
			}
			p.pos++
			continue
		}
		b.WriteByte(c)
		p.pos++
	}
	return "", fmt.Errorf("unterminated string")
}

