{"command": "cat > /workspace/internal/compile/compile.go <<'EOF'
// Package compile implements gomplate's template rendering pipeline.
package compile

import (
	"bytes"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
	"text/template"
	"time"

	"gomplate/internal/config"
	"gomplate/internal/data"
	"gomplate/internal/funcs"
)

// Compiler holds the state for rendering templates.
type Compiler struct {
	Config *config.Config
	Data   *data.Context
	Log    *slog.Logger
}

// New creates a new Compiler.
func New(cfg *config.Config, log *slog.Logger) (*Compiler, error) {
	data.InitTypeParam()
	dctx := data.NewContext()
	for alias, ds := range cfg.Datasources {
		if _, err := dctx.AddDatasource(alias, ds.URL, ds.Header); err != nil {
			return nil, err
		}
	}
	for alias, ds := range cfg.Context {
		if _, ok := dctx.Datasources[alias]; ok {
			return nil, fmt.Errorf("can't use datasource alias '%s' twice!", alias)
		}
		if _, err := dctx.AddContextDatasource(alias, ds.URL, ds.Header); err != nil {
			return nil, err
		}
	}
	for alias, ds := range cfg.Templates {
		if _, err := dctx.AddTemplateSource(alias, ds.URL, ds.Header); err != nil {
			return nil, err
		}
	}
	return &Compiler{Config: cfg, Data: dctx, Log: log}, nil
}

// Run renders the templates according to the configuration.
func (c *Compiler) Run() error {
	start := time.Now()
	if c.Config.In != "" {
		return c.renderIn()
	}
	if c.Config.InputDir != "" {
		return c.renderInputDir()
	}
	return c.renderFiles()
}

func (c *Compiler) contextValue() (map[string]interface{}, error) {
	ctx := map[string]interface{}{}
	for alias, ds := range c.Data.Context {
		v, err := ds.Value()
		if err != nil {
			return nil, err
		}
		if alias == "." {
			if m, ok := v.(map[string]interface{}); ok {
				for k, val := range m {
					ctx[k] = val
				}
				continue
			}
			return nil, fmt.Errorf("context datasource must be a map")
		}
		ctx[alias] = v
	}
	env := map[string]string{}
	for _, kv := range os.Environ() {
		i := strings.IndexByte(kv, '=')
		if i < 0 {
			continue
		}
		env[kv[:i]] = kv[i+1:]
	}
	if _, ok := ctx["Env"]; !ok {
		ctx["Env"] = &env
	}
	return ctx, nil
}

// newTemplate creates a template with all functions and external templates.
func (c *Compiler) newTemplate(name string) (*template.Template, error) {
	t := template.New(name)
	t.Delims(c.Config.LeftDelim, c.Config.RightDelim)
	ctx := &funcs.Context{
		Config:   c.Config,
		Data:     c.Data,
		Template: t,
		Name:     name,
		Log:      c.Log,
	}
	t = funcs.AddFuncs(t, ctx)
	ctx.Template = t
	switch c.Config.MissingKey {
	case "zero":
		t.Option("missingkey=zero")
	case "default", "invalid", "":
		t.Option("missingkey=default")
	default:
		t.Option("missingkey=error")
	}
	for alias, src := range c.Data.Templates {
		content, err := src.String()
		if err != nil {
			return nil, err
		}
		if _, err := t.New(alias).Parse(content); err != nil {
			return nil, err
		}
	}
	return t, nil
}

func (c *Compiler) renderIn() error {
	t, err := c.newTemplate("<arg>")
	if err != nil {
		return fmt.Errorf("failed to gather templates for rendering: %w", err)
	}
	ctx, err := c.contextValue()
	if err != nil {
		return err
	}
	var b bytes.Buffer
	if err := t.Execute(&b, ctx); err != nil {
		return fmt.Errorf("failed to render template <arg>: %w", err)
	}
	return c.writeOutput(b.String(), c.Config.In, c.OutputFile(0))
}

// OutputFile returns the output file for the given input index.
func (c *Compiler) OutputFile(i int) string {
	if len(c.Config.OutputFiles) == 0 {
		return "-"
	}
	if i >= len(c.Config.OutputFiles) {
		return "-"
	}
	return c.Config.OutputFiles[i]
}

func (c *Compiler) renderFiles() error {
	inputs := c.Config.InputFiles
	rendered := 0
	for i, in := range inputs {
		var content string
		var name string
		if in == "-" {
			content = string(c.Data.Stdin())
			name = "stdin"
		} else {
			b, err := os.ReadFile(strings.TrimPrefix(in, "/"))
			if err != nil {
				return err
			}
			content = string(b)
			name = in
		}
		t, err := c.newTemplate(name)
		if err != nil {
			return fmt.Errorf("failed to gather templates for rendering: %w", err)
		}
		ctx, err := c.contextValue()
		if err != nil {
			return err
		}
		var buf bytes.Buffer
		if err := t.Execute(&buf, ctx); err != nil {
			return fmt.Errorf("failed to render template %s: %w", name, err)
		}
		out := c.OutputFile(i)
		if err := c.writeOutput(buf.String(), name, out); err != nil {
			return err
		}
		rendered++
	}
	return c.logRendered(rendered)
}

func (c *Compiler) logRendered(n int) error {
	if c.Log != nil {
		c.Log.Debug("completed rendering", "templatesRendered", n, "errors", 0, "duration", time.Since(start(c)))
	}
	return nil
}

var startTime time.Time

func start(c *Compiler) time.Time { return startTime }

func (c *Compiler) writeOutput(content, inputName, outputFile string) error {
	if c.Config.ExecPipe {
		if len(c.Config.PostExec) == 0 {
			return nil
		}
		// write to the post-exec command's stdin
		return runPostExec(c.Config.PostExec, content, true)
	}
	switch outputFile {
	case "-", "":
		fmt.Print(content)
		return nil
	}
	dir := filepath.Dir(outputFile)
	mode, err := c.Config.FileMode()
	if err != nil {
		return err
	}
	if mode == 0 {
		if st, err := os.Stat(inputName); err == nil {
			mode = uint32(st.Mode().Perm())
		} else {
			mode = 0644
		}
	}
	if dir != "" && dir != "." {
		if err := os.MkdirAll(dir, os.ModePerm); err != nil {
			return err
		}
	}
	if strings.TrimSpace(content) == "" {
		return nil
	}
	return os.WriteFile(outputFile, []byte(content), os.FileMode(mode))
}

func (c *Compiler) renderInputDir() error {
	outDir := c.Config.OutputDir
	if err := os.MkdirAll(outDir, os.ModePerm); err != nil {
		return err
	}
	var files []string
	err := filepath.Walk(c.Config.InputDir, func(p string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}
		files = append(files, p)
		return nil
	})
	if err != nil {
		return fmt.Errorf("walkDir: %w", err)
	}
	sort.Strings(files)
	rendered := 0
	for _, f := range files {
		rel, err := filepath.Rel(c.Config.InputDir, f)
		if err != nil {
			return err
		}
		if c.shouldExclude(rel) {
			continue
		}
		outPath := filepath.Join(outDir, rel)
		if c.Config.OutputMap != "" {
			t, err := c.newTemplate("<arg>")
			if err != nil {
				return err
			}
			ctx, err := c.outputMapContext(rel)
			if err != nil {
				return err
			}
			var buf bytes.Buffer
			if err := t.Execute(&buf, ctx); err != nil {
				return fmt.Errorf("failed to render template <arg>: %w", err)
			}
			outPath = strings.TrimSpace(buf.String())
		}
		if c.excludedProcessing(rel) {
			if err := copyFile(f, outPath); err != nil {
				return err
			}
			continue
		}
		content, err := os.ReadFile(f)
		if err != nil {
			return err
		}
		t, err := c.newTemplate(f)
		if err != nil {
			return fmt.Errorf("failed to gather templates for rendering: %w", err)
		}
		ctx, err := c.contextValue()
		if err != nil {
			return err
		}
		var buf bytes.Buffer
		if err := t.Execute(&buf, ctx); err != nil {
			return fmt.Errorf("failed to render template %s: %w", rel, err)
		}
		if err := c.writeOutput(buf.String(), f, outPath); err != nil {
			return err
		}
		rendered++
	}
	return c.logRendered(rendered)
}

func (c *Compiler) outputMapContext(in string) (map[string]interface{}, error) {
	ctx, err := c.contextValue()
	if err != nil {
		return nil, err
	}
