	return c.logRendered(rendered)
}

func (c *Compiler) outputMapContext(in string) (map[string]interface{}, error) {
	ctx, err := c.contextValue()
	if err != nil {
		return nil, err
	}
	m := map[string]interface{}{}
	for k, v := range ctx {
		if k != "in" && k != "ctx" {
			m[k] = v
		}
	}
	m["in"] = in
	m["ctx"] = ctx
	return m, nil
}

func (c *Compiler) shouldExclude(rel string) bool {
	for _, ex := range c.Config.Excludes {
		exclude := true
		pattern := ex
		if strings.HasPrefix(pattern, "!") {
			exclude = false
			pattern = strings.TrimPrefix(pattern, "!")
		}
		ok, err := path.Match(pattern, rel)
		if err != nil {
			continue
		}
		if ok {
			return exclude
		}
	}
	return false
}

func (c *Compiler) excludedProcessing(rel string) bool {
	for _, ex := range c.Config.ExcludeProcessing {
		ok, err := path.Match(ex, rel)
		if err != nil {
			continue
		}
		if ok {
			return true
		}
	}
	return false
}

func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	st, err := in.Stat()
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(dst), os.ModePerm); err != nil {
		return err
	}
	out, err := os.OpenFile(dst, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, st.Mode().Perm())
	if err != nil {
		return err
	}
	defer out.Close()
	_, err = io.Copy(out, in)
	return err
}

func runPostExec(args []string, input string, pipe bool) error {
	return runCommand(args, input, pipe, nil)
}
