// runCommand runs a command, optionally piping input to its stdin.
func runCommand(args []string, input string, pipe bool, extraEnv []string) error {
	if len(args) == 0 {
		return nil
	}
	cmd := exec.Command(args[0], args[1:]...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if pipe {
		cmd.Stdin = bytes.NewBufferString(input)
	} else {
		cmd.Stdin = os.Stdin
	}
	if len(extraEnv) > 0 {
		cmd.Env = append(os.Environ(), extraEnv...)
	}
	if err := cmd.Run(); err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			os.Exit(ee.ExitCode())
		}
		return err
	}
	return nil
}

