func (a Addr) IsUnspecified() bool { return a.ip.IsUnspecified() }

// IsGlobalUnicast reports whether the address is a global unicast address.
func (a Addr) IsGlobalUnicast() bool { return a.ip.IsGlobalUnicast() }

