}

// Compare compares two addresses.
func (a Addr) Compare(o Addr) int { return a.ip.Compare(o.ip) }

// Less reports whether the address sorts before the other.
func (a Addr) Less(o Addr) bool { return a.ip.Less(o.ip) }

// Prefix is an IP prefix.
type Prefix struct {
	p netip.Prefix
}

// PrefixOf returns a Prefix wrapping the given prefix.
func PrefixOf(p netip.Prefix) Prefix { return Prefix{p: p} }

// Prefix returns the underlying prefix.
func (p Prefix) Prefix() netip.Prefix { return p.p }

// IsValid reports whether the prefix is valid.
func (p Prefix) IsValid() bool { return p.p.IsValid() }

// String returns the string form of the prefix.
func (p Prefix) String() string { return p.p.String() }

// Addr returns the base address of the prefix.
func (p Prefix) Addr() Addr { return Addr{ip: p.p.Addr()} }

// Bits returns the number of bits in the prefix.
func (p Prefix) Bits() int { return p.p.Bits() }

// Masked returns the prefix with all host bits cleared.
func (p Prefix) Masked() Prefix { return Prefix{p: p.p.Masked()} }

// Contains reports whether the address is within the prefix.
func (p Prefix) Contains(a Addr) bool { return p.p.Contains(a.ip) }

// Overlaps reports whether the prefixes overlap.
func (p Prefix) Overlaps(o Prefix) bool { return p.p.Overlaps(o.p) }

// HostBits returns the number of host bits in the prefix.
func (p Prefix) HostBits() int { return p.p.Addr().BitLen() - p.p.Bits() }

// Range returns the range of addresses covered by the prefix.
func (p Prefix) Range() string {
	from := p.p.Addr()
	last := bigFromAddr(from)
	last.Add(last, big.NewInt(int64(p.Hosts())-1))
	return from.String() + "-" + AddrOf(bigToAddr(last, p.p.Addr().BitLen())).String()
