func try(name string, key []byte, ct []byte) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return
	}
	if len(ct)%block.BlockSize() != 0 {
		return
	}
	iv := ct[:block.BlockSize()]
	data := ct[block.BlockSize():]
	out := make([]byte, len(data))
	cipher.NewCBCDecrypter(block, iv).CryptBlocks(out, data)
	pad := int(out[len(out)-1])
	if pad == 0 || pad > 16 {
		return
	}
	ok := true
	for i := len(out) - pad; i < len(out); i++ {
		if out[i] != byte(pad) {
			ok = false
		}
	}
	if !ok {
		return
	}
	fmt.Printf("MATCH %s -> %q\n", name, string(out[:len(out)-pad]))
}

func main() {
	ct, _ := base64.StdEncoding.DecodeString("Gp2WG/fKOUsVlhcpr3oqgR+fRUNBcO1eZJ9CW+gDI18=")
	pw := "swordfish"
	h := sha256.Sum256([]byte(pw))
	try("sha256[:16]", h[:16], ct)
	try("sha256[:32]", h[:], ct)
	try("sha256hex16", []byte(fmt.Sprintf("%x", h[:16])), ct)
	h1 := sha1.Sum([]byte(pw))
	try("sha1[:16]", h1[:16], ct)
	m := md5.Sum([]byte(pw))
	try("md5", m[:], ct)
	h5 := sha512.Sum512([]byte(pw))
	try("sha512[:16]", h5[:16], ct)
	try("sha512[:32]", h5[:32], ct)
	h3 := sha3.Sum256([]byte(pw))
	try("sha3_256[:16]", h3[:16], ct)
	// pbkdf2-ish? try simple
	try("raw16", []byte(pw+pw)[:16], ct)
	_ = strconv.Itoa
}
