// Package plugin implements gomplate's external plugin support.
package plugin

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"time"
)

// Plugin is an external command exposed as a template function.
type Plugin struct {
	Name    string
	Cmd     string
	Args    []string
	Pipe    bool
	Timeout time.Duration
}

// Run invokes the plugin with the given arguments.
func (p *Plugin) Run(args ...interface{}) (string, error) {
	var input string
	argv := make([]string, 0, len(p.Args)+len(args))
	argv = append(argv, p.Args...)
	for _, a := range args {
		s := fmt.Sprintf("%v", a)
		if p.Pipe {
			input = s
			continue
		}
		argv = append(argv, s)
	}
	cmd := exec.Command(p.Cmd, argv...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if p.Pipe {
		cmd.Stdin = strings.NewReader(input)
	}
	if err := cmd.Start(); err != nil {
		return "", fmt.Errorf("starting command: %w", err)
	}
	done := make(chan error, 1)
	go func() { done <- cmd.Wait() }()
	select {
	case err := <-done:
		if err != nil {
			if _, ok := err.(*exec.ExitError); ok {
				io.Copy(os.Stderr, &stderr)
				return "", fmt.Errorf("plugin %s failed: %w", p.Name, err)
			}
			return "", err
		}
	case <-time.After(p.Timeout):
		if cmd.Process != nil {
			cmd.Process.Kill()
		}
		return "", fmt.Errorf("plugin %s timed out", p.Name)
	}
	return stdout.String(), nil
}
EOF
