// Plugin is an external command exposed as a template function.
type Plugin struct {
	Name    string
	Cmd     string
	Args    []string
	Pipe    bool
	Timeout time.Duration
}

// Run invokes the plugin with the given arguments.
func (p *Plugin) Run(args ...interface{}) (string, error) {
	var input string
	argv := make([]string, 0, len(p.Args)+len(args))
	argv = append(argv, p.Args...)
	for _, a := range args {
		s := fmt.Sprintf("%v", a)
		if p.Pipe {
			input = s
			continue
		}
		argv = append(argv, s)
	}
	cmd := exec.Command(p.Cmd, argv...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if p.Pipe {
		cmd.Stdin = strings.NewReader(input)
	}
	if err := cmd.Start(); err != nil {
		return "", fmt.Errorf("starting command: %w", err)
	}
	done := make(chan error, 1)
	go func() { done <- cmd.Wait() }()
	select {
