				io.Copy(os.Stderr, &stderr)
				return "", fmt.Errorf("plugin %s failed: %w", p.Name, err)
			}
			return "", err
		}
	case <-time.After(p.Timeout):
		if cmd.Process != nil {
			cmd.Process.Kill()
		}
		return "", fmt.Errorf("plugin %s timed out", p.Name)
	}
	return stdout.String(), nil
}
